/* SF Money Trail — single-page app. Routes are hash-based so the site opens straight from the file system. */
(() => {
  'use strict';
  const C = window.FD_CORE, { esc, money, full } = window.FDC, main = document.getElementById('main');
  if (!C) { main.innerHTML = '<div class="empty"><h1>Data did not load</h1><p>Run <code>python3 scripts/build_site.py</code> and reload.</p></div>'; return; }

  /* ---------- vocabulary ---------- */
  const TIER = {
    PROVEN: { label: 'Proven', long: 'Proven', help: 'A conviction, a guilty plea, or conduct formally admitted.', icon: '<path d="M8 1.2a6.8 6.8 0 1 0 0 13.6A6.8 6.8 0 0 0 8 1.2Zm3.4 5.3-4 4.1a.8.8 0 0 1-1.1 0L4.5 8.8l1.1-1.1 1.2 1.2 3.5-3.5 1.1 1.1Z" fill="currentColor"/>' },
    CHARGED: { label: 'Charged', long: 'Charged — not proven', help: 'Alleged by prosecutors or the City Attorney. Not decided by a court.', icon: '<path d="M8 1.3 15 14H1L8 1.3Zm-.8 4.9v4h1.6v-4H7.2Zm0 5v1.5h1.6v-1.5H7.2Z" fill="currentColor"/>' },
    OFFICIAL: { label: 'Official finding', long: 'Official finding', help: 'Found by an auditor, the Controller, the Ethics Commission or a grand jury. Not a criminal finding.', icon: '<path d="M3 1.5h7l3 3v10H3v-13Zm2 5v1.4h6V6.5H5Zm0 3v1.4h6V9.5H5Z" fill="currentColor"/>' },
    REDFLAG: { label: 'Lead', long: 'Lead — unexplained', help: 'An anomaly in the records that no authority has ruled on. A question, not an accusation.', icon: '<path d="M6.8 1.5a5.3 5.3 0 0 1 4.2 8.6l3.5 3.5-1.3 1.3-3.5-3.5A5.3 5.3 0 1 1 6.8 1.5Zm0 1.8a3.5 3.5 0 1 0 0 7 3.5 3.5 0 0 0 0-7Z" fill="currentColor"/>' },
    CLEARED: { label: 'Checked — nothing unusual', long: 'Checked — nothing unusual', help: 'A test that was run on the records and turned up nothing out of the ordinary.', icon: '<path d="M8 1.2a6.8 6.8 0 1 0 0 13.6A6.8 6.8 0 0 0 8 1.2Zm0 1.6a5.2 5.2 0 1 1 0 10.4A5.2 5.2 0 0 1 8 2.8Zm2.5 2.9L7 9.2 5.6 7.8 4.5 8.9 7 11.4l4.6-4.6-1.1-1.1Z" fill="currentColor"/>' },
  };
  const tier = (t, long) => `<span class="tier ${esc(t)}" title="${esc(TIER[t]?.help || '')}"><svg viewBox="0 0 16 16" aria-hidden="true">${TIER[t]?.icon || ''}</svg>${esc(long ? TIER[t].long : TIER[t]?.label || t)}</span>`;
  const PHASE = {
    convicted: { label: 'Convicted or admitted', mark: '✓', help: 'A court, or the person themselves, has settled it. This one has been found.' },
    'in-court': { label: 'In court', mark: '◐', help: 'Charged and not yet decided.' },
    active: { label: 'Active', mark: '●', help: 'The pattern is still in the latest records, or the finding is recent. It may be happening now. Nobody has been accused by this label.' },
    past: { label: 'Past', mark: '○', help: 'The records behind it end before 2024. It may have stopped; no authority has ruled on it.' },
  };
  const phase = (c, long) => PHASE[c.phase] ? `<span class="phase ph-${esc(c.phase)}" title="${esc(PHASE[c.phase].help)}"><i aria-hidden="true">${PHASE[c.phase].mark}</i>${esc(PHASE[c.phase].label)}${long && c.phase === 'active' ? ' — still in the latest records' : ''}</span>` : '';
  /* what each person was charged with and what came of it (the case-outcomes screen, merged at build) */
  const outcomeBlock = c => { const o = c.outcome; if (!o || !(o.parties || []).length) return '';
    const sent = x => [x.custody, x.fine && (/fine|penalt/i.test(x.fine) ? x.fine : 'Fine: ' + x.fine), x.restitution && (/restitution|repay/i.test(x.restitution) ? x.restitution : 'Repayment: ' + x.restitution), x.other].filter(Boolean).join(' · ');
    return `<section class="block" id="outcome"><h2>${c.tier === 'PROVEN' ? 'What they were convicted of, and what happened next' : 'What they are charged with, and where it stands'}</h2>
      <p class="sub">${c.tier === 'PROVEN' ? 'From court and prosecutors’ documents on file. “Not on file” means no document here records it, not that it did not happen.' : 'A charge is an accusation. Nothing here has been decided by a court unless the row says so.'}</p>
      <div class="table-wrap"><table class="outcome"><thead><tr><th>Who</th><th>Charges</th><th>Plea or verdict</th><th>Sentence or penalty</th><th>Where it stands</th></tr></thead><tbody>
      ${o.parties.map(x => `<tr><td><b>${esc(x.name)}</b>${x.role ? `<small>${esc(x.role)}</small>` : ''}</td><td>${(x.charges || []).length ? `<ul>${x.charges.map(ch => `<li>${esc(ch)}</li>`).join('')}</ul>` : '<span class="muted">Not on file</span>'}</td>
        <td>${esc(x.disposition || 'Not decided')}${x.date ? `<small>${esc(fmtDate(x.date))}</small>` : ''}</td><td>${esc(sent(x.sentence || {}) || (c.tier === 'PROVEN' ? 'Not on file' : 'None: not decided'))}</td>
        <td>${esc(x.status || 'Not on file')}${(x.sources || []).filter(q => /^https:/.test(q.u || '')).slice(0, 2).map(q => `<small><a href="${esc(q.u)}" target="_blank" rel="noopener">${esc(q.t || 'Source')} ↗</a></small>`).join('')}</td></tr>`).join('')}
      </tbody></table></div>${o.note ? `<p class="small muted">${esc(o.note)}</p>` : ''}</section>`; };
  const outcomeNote = c => '';
  const KIND = { money: 'Money', gift: 'Gift or benefit', decision: 'Official decision', control: 'Controls', family: 'Family tie', employment: 'Employs / paid by', ownership: 'Owns', information: 'Information passed' };
  const SIG = { 'new-large': 'New and large', rocket: 'Rapid growth', cliff: 'Sudden stop', nobid: 'Mostly no-bid', 'near-10m': 'Contracts just under $10M', 'monitoring-repeat': 'Repeat audit findings', 'approval-window': 'Officer gave to approver', 'political-direct': 'Funds political committees', gifts: 'Gifts to its funders', standing: 'Not in good standing', 'audit-weakness': 'Auditors flagged its controls', tier: 'On the Controller’s watch list', debarred: 'Suspended or debarred', 'insider-deals': 'Deals with insiders', diversion: 'Reported a diversion of assets', 'no-staff': 'No employees of its own', 'one-vendor': 'One contractor takes most of the budget', 'late-return': 'Tax return missing or late', ppp: 'Federal PPP loan too', 'federal-direct': 'Also paid directly by federal agencies', outcomes: 'Outcome data on file' };
  const DEPT = { DPH: 'Public Health', HOM: 'Homelessness & Supportive Housing', HSA: 'Human Services', CHF: 'Children, Youth & Families', MYR: "Mayor's Office (housing & community development)", ECN: 'Economic & Workforce Development', ADM: 'City Administrator', DEC: 'Early Childhood', HRC: 'Human Rights Commission', REC: 'Recreation & Park', POL: 'Police', DPW: 'Public Works', PUC: 'Public Utilities', MTA: 'Municipal Transportation', AIR: 'Airport', ART: 'Arts Commission', SHF: 'Sheriff', FIR: 'Fire', LIB: 'Library', HRD: 'Human Resources', PRT: 'Port', JUV: 'Juvenile Probation', ADP: 'Adult Probation', DAT: 'District Attorney', WOM: 'Status of Women', ENV: 'Environment', CFC: 'Children & Families Commission', TIS: 'Technology', CAT: 'City Attorney', CPC: 'Planning', DPA: 'Police Accountability', HSS: 'Health Service System', DBI: 'Building Inspection', RNT: 'Rent Board', DEM: 'Emergency Management', CON: 'Controller', TTX: 'Treasurer & Tax Collector', REG: 'Elections', ASR: 'Assessor-Recorder', BOS: 'Board of Supervisors', WAR: 'War Memorial', FAM: 'Fine Arts Museums', AAM: 'Asian Art Museum', SCI: 'Academy of Sciences', RET: 'Retirement System', PDR: 'Public Defender', CSS: 'Child Support Services', ETH: 'Ethics Commission', LLB: 'Law Library' };
  const dept = c => DEPT[c] ? `${DEPT[c]}` : c;
  const sigName = id => { const t = String(id || '').replace(/-/g, ' '); return t.charAt(0).toUpperCase() + t.slice(1); };
  const byId = Object.fromEntries(C.cases.map(c => [c.id, c])), patterns = Object.fromEntries(C.patterns.map(p => [p.id, p]));
  const fmtDate = d => { if (!d) return ''; const m = String(d).match(/^(\d{4})(?:-(\d{2}))?(?:-(\d{2}))?/); if (!m) return d; const mo = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']; return m[3] ? `${+m[3]} ${mo[+m[2] - 1]} ${m[1]}` : m[2] ? `${mo[+m[2] - 1]} ${m[1]}` : m[1]; };
  /* the days the raw data was pulled: the first pull (C.pulled, the main datasets) to the latest dated pull */
  const pulledSpan = () => { const p = (C.pulls || []).filter(d => d >= C.pulled), last = p[p.length - 1]; return last && last !== C.pulled ? `${fmtDate(C.pulled)} to ${fmtDate(last)}` : fmtDate(C.pulled); };
  const amount = c => c.amount && typeof c.amount.value === 'number' ? (c.amount.kind === 'none' ? c.amount.value.toLocaleString('en-US') : money(c.amount.value)) : '';   // kind 'none' = a count, not dollars
  const ICON = { check: '<path d="M6.5 11.2 3.3 8l1.1-1.1 2.1 2.1 5-5L12.7 5l-6.2 6.2Z" fill="currentColor"/>', x: '<path d="m4 5.1 1.1-1.1L8 6.9 10.9 4 12 5.1 9.1 8l2.9 2.9-1.1 1.1L8 9.1 5.1 12 4 10.9 6.9 8 4 5.1Z" fill="currentColor"/>', q: '<path d="M8 2a3.6 3.6 0 0 1 2 6.6c-.8.5-1.2 1-1.2 1.9H7.2c0-1.600.8-2.500 1.900-3.200A2 2 0 1 0 6 5.600H4.400A3.600 3.600 0 0 1 8 2Zm-.9 10h1.800v1.800H7.100V12Z" fill="currentColor"/>', arrow: '<path d="M3 7.200h7.300L7.600 4.500l1.100-1.100L13.300 8l-4.600 4.600-1.100-1.100 2.700-2.700H3V7.200Z" fill="currentColor"/>', quote: '<path d="M3 4h4.500v4.500c0 2-1.300 3.300-3.500 3.500v-1.500c1-.2 1.600-.9 1.600-2H3V4Zm5.500 0H13v4.500c0 2-1.300 3.300-3.500 3.500v-1.500c1-.2 1.600-.9 1.600-2H8.500V4Z" fill="currentColor"/>' };
  const ic = n => `<svg viewBox="0 0 16 16" aria-hidden="true">${ICON[n]}</svg>`;

  /* ---------- lazy data ---------- */
  const loaded = {};
  const need = name => loaded[name] || (loaded[name] = new Promise((res, rej) => { const s = document.createElement('script'); s.src = `assets/data/${name}.js?v=${String(C.built || '').replace(/\D/g, '')}`; s.onload = () => res(window['FD_' + name.toUpperCase()]); s.onerror = () => rej(new Error('Could not load ' + name)); document.head.appendChild(s); }));

  /* ---------- small renderers ---------- */
  const caseCard = c => `<a class="card case-card bar-${esc(c.tier)}" href="#case/${esc(c.id)}"><div class="row">${tier(c.tier)}${phase(c)}<span class="tag">${esc(c.category)}</span></div><h3>${esc(c.title)}</h3><p>${esc(c.oneLine)}</p>${c.movie ? `<span class="film">film · ${Math.round(c.movie.s / 60)} min</span>` : ''}
    <div class="point"><span class="pin">1</span><span><b>${esc(c.suspicious[0].title)}.</b> ${esc(c.suspicious[0].what)}</span></div>
    <div class="meta">${amount(c) ? `<span class="amt">${esc(amount(c))}</span><span>${esc(c.amount.label)}</span>` : ''}</div></a>`;
  const head = (eyebrow, title, lede) => `<div class="page-h"><div class="eyebrow">${esc(eyebrow)}</div><h1>${title}</h1>${lede ? `<p class="lede">${lede}</p>` : ''}</div>`;
  const stat = (v, l, d, href) => `<div class="card stat"><div class="v">${esc(v)}</div><div class="l">${l}</div>${d ? `<div class="d">${d}</div>` : ''}${href ? `<a href="${href}">See the records →</a>` : ''}</div>`;
  const chartBox = (id, title, sub) => `<div class="card pad"><div class="chart-h"><h3>${esc(title)}</h3></div>${sub ? `<p class="small muted">${sub}</p>` : ''}<div class="chart" id="${id}"></div></div>`;
  const tableOf = (cols, rows, opts = {}) => `<div class="table-wrap"><table><thead><tr>${cols.map(c => `<th class="${c.num ? 'num' : ''}">${esc(c.h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r => `<tr>${cols.map(c => `<td class="${c.num ? 'num' : ''}">${c.f(r)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${!rows.length ? `<div class="empty">${esc(opts.empty || 'Nothing matches.')}</div>` : ''}`;
  const MONEY_TABS = [['gifts', 'Gifts to officials'], ['penalties', 'Ethics penalties'], ['window', 'Donations near contract approvals'], ['direct', 'Nonprofits funding politics']], CONTRACT_TABS = [['line', 'The $10 million line'], ['split', 'Purchases just under the limit'], ['award', 'Bid or no bid']];
  const after = [];            // functions to run once the page HTML is in the DOM
  const S = { phase: '', q: '', tier: '', cat: '', pat: '', page: 1, sig: '', sort: 'total', own: true, strip: 0, tab: '' };

  /* ---------- briefing ---------- */
  function briefing() {
    const st = C.stats, fy = st.ngoByFY, first = Object.keys(fy)[0], last = Object.keys(fy).slice(-1)[0], m = st.awardMethod, mt = Object.values(m).reduce((a, b) => a + b, 0) || 1;
    const picks = (C.featured || []).length ? C.featured.map(i => byId[i]) : []; if (!picks.length) ['PROVEN', 'CHARGED', 'OFFICIAL', 'REDFLAG'].forEach(t => picks.push(...C.cases.filter(c => c.tier === t).slice(0, 2)));
    const pc = {}; C.cases.forEach(c => (c.patterns || []).forEach(p => pc[p] = (pc[p] || 0) + 1));
    const ok = picks.filter(Boolean), lead = ok.filter(c => c.tier !== 'REDFLAG').slice(0, 6), fresh = ok.filter(c => c.tier === 'REDFLAG').slice(-3).reverse();
    return `<section class="hero"><div><div class="eyebrow">San Francisco public money · edition ${esc(fmtDate(C.edition))}</div>
      <h1>Where the money goes wrong — <em>and how sure we are.</em></h1>
      <p class="lede">Every case names the exact record that looks wrong, draws the money trail around it, and says how strong the evidence is: proven in court, charged, found by auditors, or still an unexplained lead.</p>
      <div class="row"><a class="btn primary" href="#cases">Open the case files</a>${C.hasMap ? '<a class="btn" href="#map">See it on the map</a>' : ''}${FDY ? '<a class="btn" href="#topics">Browse by topic</a>' : ''}<a class="btn" href="#orgs">Look up a name</a></div></div>
      <div class="ladder" aria-label="Cases by strength of evidence">${['PROVEN', 'CHARGED', 'OFFICIAL', 'REDFLAG'].map(t => `<a class="bar-${t}" href="#cases?tier=${t}"><b>${st.tiers[t] || 0}</b><span><strong>${esc(TIER[t].long)}</strong>${esc(TIER[t].help)}</span></a>`).join('')}</div></section>
    ${st.phases ? `<section class="phases" aria-label="Cases by where they stand"><span class="ph-h">Where the cases stand</span>${Object.keys(PHASE).map(k => `<a href="#cases?phase=${k}" class="ph-b ph-${k}" title="${esc(PHASE[k].help)}"><b>${st.phases[k] || 0}</b><span><i aria-hidden="true">${PHASE[k].mark}</i>${esc(PHASE[k].label)}</span></a>`).join('')}<span class="ph-n">“Active” means the pattern is still in the latest records. It is not an accusation.</span></section>` : ''}
    <section class="section"><h2>Start here</h2><p class="sub">The strongest cases at each level of proof. The numbered box on each card is the single record to look at first.</p><div class="grid g2">${lead.map(caseCard).join('')}</div></section>
    ${fresh.length ? `<section class="section"><h2>The newest leads</h2><p class="sub">Unexplained patterns in the records that no authority has ruled on. Each is a question for the records, not an accusation.</p><div class="grid g2">${fresh.map(caseCard).join('')}</div><p style="margin-top:14px"><a class="btn" href="#cases">All ${C.cases.length} case files →</a></p></section>` : ''}
    <section class="section"><h2>The scale, in four numbers</h2><p class="sub">Computed from the City's own records, pulled ${esc(pulledSpan())}.</p><div class="grid g4">
      ${stat(money(fy[last]), `paid to nonprofits in fiscal ${esc(last)}`, `Up from ${money(fy[first])} in ${esc(first)} — ${Math.round((fy[last] / fy[first] - 1) * 100)}% more in ${last - first} years.`, '#orgs')}
      ${stat(money(m.nobid || 0), 'went to nonprofits without competition since 2019', `No-bid, sole-source or emergency authority. $${Math.round((st.award ? st.award.noBidByYear[2026] : 0) / 1e6)}M in fiscal 2026 alone, up from $${Math.round((st.award ? st.award.noBidByYear[2019] : 0) / 1e6)}M in 2019.`, '#contracts/award')}
      ${stat(`${st.line10M.justBelow_9_5_to_10} vs ${st.line10M.justAbove_10_to_10_5}`, 'contracts just under vs just over $10 million', `The historical $10M spending rule covered nonconstruction agreements. ${st.line10M.exact_9999999} contracts are exactly $9,999,999.`, '#contracts/line')}
      ${stat(String(st.window.strong), 'donations from a contractor’s own officers to the officials approving its contract', 'Name and employer both match, inside the legal no-contribution window. Each needs checking.', '#money/window')}</div></section>
    ${st.wave2 && FDX ? `<section class="section"><h2>Four more, from the wider search</h2><p class="sub">Beyond nonprofits: results, payroll, approvals and influence. The full list of searches, and what each found, is in the <a href="#plan">plan</a>.</p><div class="grid g4">
      ${stat('+' + st.wave2['outcomes.homelessMoneyPct'] + '%', 'homelessness payments to nonprofits since fiscal 2019', `Over the same years the count of homeless people changed by ${st.wave2['outcomes.homelessCountPct']}%.`, '#outcomes')}
      ${stat(st.wave2['ot.doubled'] + ' vs ' + st.wave2['ot.doubledFirst'], 'City employees paid more in overtime than in salary: latest year vs 2014', 'The largest record shows more than 16 paid hours for every day of the year.', '#contracts/overtime')}
      ${stat(String(st.wave2['retro.total']), 'contracts the Board approved after they had already begun', money(st.wave2['retro.value']) + ' in agreements since 2014.', '#contracts/retro')}
      ${stat(String(st.wave2['lobby.afterBan']), 'lobbyist contributions since the 2018 ban tied to officials they lobbied', 'Most to City campaigns; the rest through party, state and independent committees.', '#money/lobby')}</div>
</section>` : ''}
    ${FDY && st.wave4 && st.wave4['permit_process.loopPermits'] != null && st.wave4['property.highestPerHome'] != null && st.wave4['fedmoney.eraShare'] != null && st.wave4['record.amend.doubled'] != null ? `<section class="section"><h2>New this edition: permits, property, relief and amendments</h2><p class="sub">From records not screened before. Each links to the page that lists every row.</p><div class="grid g4">
      ${stat(st.wave4['permit_process.loopPermits'].toLocaleString('en-US'), 'building permits since 2015 taken out only to finish an earlier permit', `The earlier permit was a median ${st.wave4['permit_process.loopMedianAgeYears']} years old. A home remodel carries a median ${st.wave4['permit_process.stackRemodelMedian']} permits.`, '#s/permit_process')}
      ${stat(money(st.wave4['property.highestPerHome']), 'a home: the most the City paid for a building bought for homeless housing', `The least was ${money(st.wave4['property.lowestPerHome'])}. ${st.wave4['property.homelessPurchases']} buildings, ${money(st.wave4['property.homelessPurchaseDollars'])} before repairs.`, '#s/property.homes-bought')}
      ${stat(Math.round(st.wave4['fedmoney.eraShare'] * 100) + '%', 'of emergency rent aid is explained by households helped times average aid', `Every one of ${st.wave4['fedmoney.eraPeers']} other California grantees is at ${Math.round(st.wave4['fedmoney.eraNextLowestShare'] * 100)}% or more. A reporting slip is the likeliest cause.`, '#s/fedmoney.rental-assistance-gap')}
      ${stat(st.wave4['record.amend.startedUnder10M'] + ' of ' + st.wave4['record.amend.doubled'], 'agreements that at least doubled by amendment began between $9 million and $10 million', `$10 million was the line for a Board vote. They now total ${money(st.wave4['record.amend.startedUnder10MLatest'])}.`, '#s/record.amendment-growth')}</div></section>` : ''}
    ${FDY ? `<section class="section"><h2>Pick a thread</h2><p class="sub">Everything on this site sits under one of these topics. Coloured counts are case files by level of proof.</p></section>${FDY.topicsGrid()}<p class="row" style="margin-top:14px"><a class="btn primary" href="#plan">Every test and its status</a><a class="btn" href="#trace">Follow one name through every channel</a><a class="btn" href="#patterns">How the schemes work</a></p>` : ''}
    ${C.changes.length ? `<section class="section"><h2>Latest findings</h2><div class="card pad">${C.changes.map(x => `<div class="change"><time>${esc(fmtDate(x.date))}</time><div>${x.tier ? tier(x.tier) + ' ' : ''}${esc(x.text)} ${x.caseId && byId[x.caseId] ? `<a href="#case/${esc(x.caseId)}">Open case →</a>` : ''}</div></div>`).join('')}</div></section>` : ''}
    <section class="section"><h2>The same few moves, again and again</h2><p class="sub">Different departments and decades, the same handful of methods. Pick one to see every case that uses it.</p><div class="grid g3">${C.patterns.filter(p => pc[p.id]).sort((a, b) => pc[b.id] - pc[a.id]).map(p => `<a class="card pad" style="text-decoration:none;color:inherit" href="#pattern/${esc(p.id)}"><div class="row" style="justify-content:space-between"><b>${esc(p.name)}</b><span class="tag">${pc[p.id]} case${pc[p.id] > 1 ? 's' : ''}</span></div><p class="small muted" style="margin:8px 0 0">${esc(p.plain)}</p></a>`).join('')}</div></section>
    <section class="section"><div class="note"><b>How to read this site.</b> A red flag is not a finding of fraud, and a charge is not a conviction. Every claim carries its source; every lead lists what the records do not show and the record that would settle it. <a href="#method">Method and data →</a></div></section>`;
  }

  /* ---------- case list ---------- */
  function casesPage() {
    const cats = [...new Set(C.cases.map(c => c.category))].sort(), q = S.q.toLowerCase();
    const list = C.cases.filter(c => (!S.tier || c.tier === S.tier) && (!S.phase || c.phase === S.phase) && (!S.cat || c.category === S.cat) && (!S.pat || (c.patterns || []).includes(S.pat)) && (!q || JSON.stringify([c.title, c.oneLine, c.actors.map(a => a.name), c.suspicious.map(s => s.title)]).toLowerCase().includes(q)));
    after.push(() => {
      const f = document.getElementById('cf'); if (!f) return;
      f.addEventListener('input', e => { if (e.target.id === 'cq') { S.q = e.target.value; rerender('cq'); } });
      f.addEventListener('change', e => { if (e.target.id === 'ccat') S.cat = e.target.value; if (e.target.id === 'cpat') S.pat = e.target.value; rerender(); });
      f.querySelectorAll('[data-tier]').forEach(b => b.addEventListener('click', () => { S.tier = S.tier === b.dataset.tier ? '' : b.dataset.tier; rerender(); }));
      f.querySelectorAll('[data-phase]').forEach(b => b.addEventListener('click', () => { S.phase = S.phase === b.dataset.phase ? '' : b.dataset.phase; rerender(); }));
    });
    return `${head('Case files', 'Every case, strongest evidence first', 'Filter by how solid the evidence is, by where the case stands, by subject, or by the method used.')}
      <details class="note labels"><summary><b>What the labels mean</b></summary>
        <p><b>Two labels on every case.</b> The first says how strong the evidence is. The second says where the matter stands in time.</p>
        <p><b>Proven</b> means a court convicted someone, someone pleaded guilty, or someone formally admitted the conduct, for example in a signed agreement with the Ethics Commission. <b>Charged</b> means a prosecutor or the City Attorney has accused someone and no court has decided; the person is presumed innocent. Each proven or charged case lists the charges, the plea or verdict, and the sentence or penalty where the documents on file record them.</p>
        <p><b>Official finding</b> means an auditor, the Controller, a grand jury or a regulator put it in writing; it is not a criminal finding. <b>Lead</b> means a pattern in the records that no authority has ruled on.</p>
        <p><b>Convicted or admitted</b> and <b>In court</b> follow from Proven and Charged. <b>Active</b> means the records behind the case reach 2024 or later, so the pattern is still in the latest data or the finding is recent; it may be happening now. <b>Past</b> means the records end earlier. Active is a statement about dates, not an accusation.</p></details>
      <form class="filters" id="cf" onsubmit="return false"><input id="cq" type="search" placeholder="Search a name, organization or topic" value="${esc(S.q)}" aria-label="Search cases">
        ${['PROVEN', 'CHARGED', 'OFFICIAL', 'REDFLAG'].map(t => `<button type="button" class="chip" data-tier="${t}" aria-pressed="${S.tier === t}">${esc(TIER[t].label)} · ${C.stats.tiers[t] || 0}</button>`).join('')}
        <span class="filter-sep" aria-hidden="true"></span>${Object.keys(PHASE).map(k => `<button type="button" class="chip" data-phase="${k}" aria-pressed="${S.phase === k}" title="${esc(PHASE[k].help)}">${PHASE[k].mark} ${esc(PHASE[k].label)} · ${(C.stats.phases || {})[k] || 0}</button>`).join('')}
        <select id="ccat" aria-label="Subject"><option value="">All subjects</option>${cats.map(c => `<option ${S.cat === c ? 'selected' : ''}>${esc(c)}</option>`).join('')}</select>
        <select id="cpat" aria-label="Method"><option value="">All methods</option>${C.patterns.map(p => `<option value="${esc(p.id)}" ${S.pat === p.id ? 'selected' : ''}>${esc(p.name)}</option>`).join('')}</select></form>
      <p class="muted small">${list.length} of ${C.cases.length} cases</p><div class="grid g2">${list.map(caseCard).join('')}</div>${!list.length ? '<div class="empty">No case matches. Clear a filter.</div>' : ''}`;
  }

  /* ---------- one case ---------- */
  function casePage(c) {
    const sidx = Object.fromEntries(c.sources.map((s, i) => [s.id, i + 1]));
    const refs = ids => (ids || []).filter(i => sidx[i]).map(i => `<a class="src" href="#case/${esc(c.id)}" data-src="${sidx[i]}" title="${esc(c.sources[sidx[i] - 1].title)}">${sidx[i]}</a>`).join('');
    const series = (c.trajectory && c.trajectory.series) || [], nameOf = id => c.actors.find(x => x.id === id).name;
    const fyOf = d => { const m = String(d).match(/^(\d{4})-(\d{2})/); return m ? 'FY' + (+m[2] >= 7 ? +m[1] + 1 : +m[1]) : null; };
    let year = '', letter = 0;
    const badges = c.links.map(l => l.flag != null ? String(l.flag) : String.fromCharCode(97 + (letter++ % 26)));
    after.push(() => { const k = document.getElementById('kit'); if (k) k.addEventListener('click', () => window.FDX.storyKit(c)); });
    after.push(() => { const k = document.getElementById('playmovie'); if (k) k.addEventListener('click', () => window.FDMOVIE.open(c, k)); });
    after.push(() => { const k = document.getElementById('records-body'); if (k) window.FDEV.mount(k, c.id); });
    after.push(() => {
      const pick = (i, scroll) => { main.querySelectorAll('#flow .edge.sel, .links li.sel').forEach(x => x.classList.remove('sel')); main.querySelector(`#flow .edge[data-link="${i}"]`)?.classList.add('sel'); const li = main.querySelector(`.links li[data-link="${i}"]`); if (li) { li.classList.add('sel'); if (scroll) li.scrollIntoView({ block: 'nearest' }); } };
      window.FDC.flow(document.getElementById('flow'), c, i => pick(i, true));
      main.querySelectorAll('.links li').forEach(li => { li.addEventListener('click', e => { if (e.target.closest('a')) return; pick(+li.dataset.link); }); li.addEventListener('keydown', e => { if (e.key === 'Enter') pick(+li.dataset.link); }); });
      const firstFlag = c.links.findIndex(l => l.flag != null); pick(firstFlag >= 0 ? firstFlag : 0);
      series.forEach((s, i) => {
        const el = document.getElementById('traj' + i); if (!el) return;
        const fyish = s.points.every(p => /^FY\d{4}$/.test(p.period) || /^\d{4}$/.test(p.period));
        if (fyish) {
          const marks = c.timeline.filter(t => t.flag != null || t.kind === 'enforcement').map(t => ({ period: /^FY/.test(s.points[0].period) ? (fyOf(t.date) || t.date) : String(t.date).slice(0, 4), n: t.flag != null ? t.flag : '!', title: fmtDate(t.date), text: t.text })).filter(m => s.points.some(p => p.period === m.period)).slice(0, 8);
          const plain = v => Math.round(v).toLocaleString('en-US');
          window.FDC.columns(el, { label: s.label, points: s.points.map(p => ({ label: p.period, short: p.period.replace('FY20', 'FY'), value: p.value })), markers: marks, ...(s.unit === 'USD' ? {} : { fmt: plain, fullFmt: plain }) });
        } else window.FDC.steps(el, { label: s.label, points: s.points, ref: s.unit === 'USD' && Math.max(...s.points.map(p => p.value)) > 1e7 && Math.min(...s.points.map(p => p.value)) < 1e7 ? { value: 1e7, label: '$10M line' } : null });
      });
      bindRefs(main);
      main.querySelectorAll('[data-point]').forEach(a => a.addEventListener('click', e => { e.preventDefault(); const el = document.getElementById('pt' + a.dataset.point); if (el) { el.scrollIntoView({ block: 'center' }); main.querySelectorAll('.point-card.hl').forEach(x => x.classList.remove('hl')); el.classList.add('hl'); } }));
      main.querySelectorAll('[data-go]').forEach(b => b.addEventListener('click', () => document.getElementById(b.dataset.go)?.scrollIntoView()));
    });
    return `<p class="small"><a href="#cases">← All cases</a></p>
    ${outcomeNote(c)}<header class="case-head bar-${esc(c.tier)}"><div class="row">${tier(c.tier, true)}${phase(c, true)}<span class="tag">${esc(c.category)}</span></div><h1>${esc(c.title)}</h1><p class="lede">${esc(c.oneLine)}</p><p class="status"><b>Where it stands:</b> ${esc(c.status)}</p>${c.movie && window.FDMOVIE ? `<button type="button" class="playmovie" id="playmovie" title="A narrated film of this case file: the story, who is in it, the numbered points, the timeline, what is and is not established, and what would settle it"><span class="tri" aria-hidden="true"></span><span>Play the film of this case<small> · ${Math.floor(c.movie.s / 60)} min ${String(Math.round(c.movie.s % 60)).padStart(2, '0')} s, with sound</small></span></button>` : ''}</header>
    <div class="glance">
      <div class="card pad bar-${esc(c.tier)}" style="border-left:5px solid var(--t)"><h3>Strength of evidence</h3>${tier(c.tier, true)}<p class="small" style="margin:8px 0 0">${esc(TIER[c.tier].help)}</p></div>
      ${amount(c) ? `<div class="card pad"><h3>The number</h3><div class="big">${esc(amount(c))}</div><p class="small" style="margin:6px 0 0">${esc(c.amount.label)}</p></div>` : ''}
      ${(c.patterns || []).length ? `<div class="card pad"><h3>The method</h3><div class="row">${c.patterns.filter(p => patterns[p]).map(p => `<a class="chip" href="#pattern/${esc(p)}">${esc(patterns[p].name)}</a>`).join('')}</div><p class="small muted" style="margin:10px 0 0">Facts as of ${esc(fmtDate(c.asOf))} · ${c.sources.length} sources</p></div>` : ''}
    </div>
    <nav class="toc" aria-label="Sections">${[...(c.outcome && (c.outcome.parties || []).length ? [['outcome', c.tier === 'PROVEN' ? 'What happened next' : 'The charges']] : []), ['story', 'What happened'], ['sus', 'The suspicious part'], ...(c.evidence && window.FDEV ? [['records', `Every record (${c.evidence.rows.toLocaleString('en-US')})`]] : []), ['money', 'Follow the money'], ...(series.length ? [['traj', 'Over time']] : []), ['time', 'Timeline'], ['sure', 'How sure are we?'], ['next', 'What would settle it'], ['srcs', 'Sources']].map(([id, t]) => `<button class="chip" data-go="${id}">${t}</button>`).join('')}${(C.caseMap || {})[c.id] ? `<a class="chip" href="${esc(C.caseMap[c.id].href)}" title="Open the map at the place this case points to">On the map: ${esc(C.caseMap[c.id].name)}</a>` : ''}${window.FDX ? '<button class="chip kit" id="kit" title="Headline, the numbered points, timeline, what is and is not established, questions and sources, as one text file">Download story kit</button>' : ''}</nav>
      ${outcomeBlock(c)}<section class="block story" id="story" style="margin-top:0"><h2>What happened</h2>${c.story.map(p => `<p>${esc(p)}</p>`).join('')}</section><section class="block" id="sus"><h2>The suspicious part</h2><p class="sub">Put your finger here. Each number appears again on the diagram and the timeline.</p><div class="points">${c.suspicious.map(p => `<article class="card point-card bar-${esc(p.tier)}" id="pt${esc(p.n)}"><span class="pin">${esc(p.n)}</span><div><div class="row" style="margin-bottom:6px">${tier(p.tier)}${p.amount ? `<b>${esc(full(p.amount))}</b>` : ''}${p.date ? `<span class="muted small">${esc(fmtDate(p.date))}</span>` : ''}</div><h3>${esc(p.title)}</h3>
        <dl><dt>What</dt><dd>${esc(p.what)} ${refs(p.sourceIds)}</dd><dt>Why it matters</dt><dd>${esc(p.why)}</dd><dt>Where to look</dt><dd>${esc(p.where)}</dd></dl></div></article>`).join('')}</div></section>
      ${c.evidence && window.FDEV ? `<section class="block" id="records"><h2>Every record behind this case</h2><div id="records-body"></div></section>` : ''}
      <section class="block" id="money"><h2>Follow the money</h2><p class="sub">Money and favours run left to right. A numbered arrow is one of the suspicious points above; lettered arrows are the surrounding links. Select an arrow or a row.</p>
        <div class="flow-wrap"><div class="flow-scroll"><div id="flow"></div></div>
        <div class="legend"><span><svg viewBox="0 0 34 10"><line x1="1" y1="5" x2="33" y2="5" stroke="currentColor" stroke-width="1.5"/></svg>Money</span><span><svg viewBox="0 0 34 10"><line x1="2" y1="5" x2="33" y2="5" stroke="currentColor" stroke-width="2.5" stroke-dasharray="1.5 5" stroke-linecap="round"/></svg>Gift or benefit</span><span><svg viewBox="0 0 34 10"><line x1="1" y1="5" x2="33" y2="5" stroke="currentColor" stroke-width="1.5" stroke-dasharray="7 5"/></svg>Decision, control or relationship</span><span><span class="pin" style="width:18px;height:18px;font-size:11px">1</span>Suspicious point</span><span><span class="lt" style="display:inline-grid;place-items:center;width:18px;height:18px;border-radius:50%;border:1.25px solid var(--axis);font-size:11px">a</span>Other link</span></div>
        <ol class="links">${c.links.map((l, i) => `<li data-link="${i}" tabindex="0" class="${l.flag != null ? 'flag' : ''}">${l.flag != null ? `<span class="pin">${esc(badges[i])}</span>` : `<span class="lt">${esc(badges[i])}</span>`}<div><div class="row"><span class="ft">${esc(nameOf(l.from))} → ${esc(nameOf(l.to))}</span><span class="tag">${esc(KIND[l.kind] || l.kind)}</span>${tier(l.tier)}</div><div class="dt"><b>${esc(l.label)}.</b> ${esc(l.detail)} ${refs(l.sourceIds)}${l.flag != null ? ` <a class="small" href="#case/${esc(c.id)}" data-point="${esc(l.flag)}">Why it is suspicious ↑</a>` : ''}</div></div></li>`).join('')}</ol>
        <div class="people"><span class="muted">Who is involved:</span>${c.actors.map(a => a.who && C.who[a.who] && C.who[a.who].cases.length > 1 ? `<a class="chip" href="#who/${esc(a.who)}" title="${esc(a.role || '')}">${esc(a.name)} · ${C.who[a.who].cases.length} cases</a>` : `<span class="chip" style="cursor:default" title="${esc(a.role || '')}">${esc(a.name)}</span>`).join('')}</div></div></section>
      ${series.length ? `<section class="block" id="traj"><h2>Over time</h2><p class="sub">${esc((c.trajectory && c.trajectory.note) || '')} Numbered markers are the suspicious points; “!” marks enforcement.</p><div class="grid g2">${series.map((s, i) => `<div class="card pad"><div class="chart-h"><h3>${esc(s.label)}</h3>${s.orgKey ? `<a class="small" href="#org/${esc(slugOf(s.orgKey))}">Full profile →</a>` : ''}</div><div class="chart" id="traj${i}"></div><details class="small"><summary class="muted">Show as table</summary>${tableOf([{ h: 'Period', f: p => esc(p.period) }, { h: 'Amount', num: 1, f: p => esc(s.unit === 'USD' ? full(p.value) : Math.round(p.value).toLocaleString('en-US')) }], s.points)}</details>${s.auto ? '<p class="small muted" style="margin:8px 0 0">Source: Controller, Citywide Nonprofit Spending (DataSF qkex-vh98), fiscal years ending June 30.</p>' : `<p class="small muted" style="margin:8px 0 0">Sources ${refs(s.sourceIds)}</p>`}</div>`).join('')}</div></section>` : ''}
      <section class="block" id="time"><h2>Timeline</h2><p class="sub">Numbered events are the suspicious points above.</p><div class="card pad"><ol class="tl">${c.timeline.map(t => { const y = String(t.date).slice(0, 4), yh = y !== year ? `<li class="yr" aria-hidden="true">${esc(year = y)}</li>` : ''; return `${yh}<li class="k-${esc(t.kind)} ${t.flag != null ? 'flag' : ''}"><time>${esc(fmtDate(t.date))}</time><span class="dot">${t.flag != null ? esc(t.flag) : ''}</span><p><span class="k">${esc(t.kind)}</span><br>${esc(t.text)} ${refs(t.sourceIds)}</p></li>`; }).join('')}</ol></div></section>
      <section class="block" id="sure"><h2>How sure are we?</h2><p class="sub">What the record establishes, what it does not, and the other side.</p><div class="cols2">
        <div class="card pad"><h3 style="font-size:16px;margin-bottom:10px">Established</h3><ul class="list">${c.established.map(x => `<li>${ic('check')}<span>${esc(x.text)} ${refs(x.sourceIds)}<br>${tier(x.tier)}</span></li>`).join('')}</ul></div>
        <div class="card pad"><h3 style="font-size:16px;margin-bottom:10px">Not established</h3><ul class="list">${c.notEstablished.map(x => `<li>${ic('x')}<span>${esc(x)}</span></li>`).join('')}</ul></div>
        ${(c.defense || []).length ? `<div class="card pad"><h3 style="font-size:16px;margin-bottom:10px">What those named say</h3><ul class="list">${c.defense.map(x => `<li>${ic('quote')}<span>${esc(x)}</span></li>`).join('')}</ul></div>` : ''}</div></section>
      <section class="block" id="next"><h2>What would settle it</h2><p class="sub">The specific records that would confirm or close this.</p><div class="card pad"><ul class="list">${c.next.map(x => `<li>${ic('arrow')}<span>${esc(x)}</span></li>`).join('')}</ul></div></section>
      ${(c.related || []).length ? `<section class="block"><h2>Connected cases</h2><div class="grid g2">${c.related.map(r => caseCard(byId[r])).join('')}</div></section>` : ''}
      <section class="block" id="srcs"><h2>Sources</h2><p class="sub">Numbers in the text point here.</p><ol class="sources card pad">${c.sources.map((s, i) => `<li id="src${i + 1}"><span class="n">${i + 1}</span><div>${/^https:\/\//.test(s.url) ? `<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a>` : esc(s.title)}<small>${esc(s.publisher)}${s.date ? ' · ' + esc(fmtDate(s.date)) : ''}${srcGet(s)}</small>${s.quote ? `<q>${esc(s.quote)}</q>` : ''}</div></li>`).join('')}</ol></section>`;
  }
  /* where a reader can get the record: the source's own public link, a DataSF CSV download, or a plain "not online" note.
     The site does not host the raw data (owner, 24 Nov 2026), so no saved copy is ever pointed to. */
  const dsId = u => (String(u || '').match(/^https:\/\/data\.sf(?:gov)?\.(?:gov|org)\/d\/([a-z0-9]{4}-[a-z0-9]{4})\/?$/) || [])[1];
  const csvUrl = id => `https://data.sf.gov/api/views/${id}/rows.csv?accessType=DOWNLOAD`;
  function sourceCsv(url) {
    const id = dsId(url);
    if (id) return csvUrl(id);
    const match = String(url || '').match(/^(https:\/\/(?:data\.sf\.gov|data\.sfgov\.org)\/resource\/[a-z0-9]{4}-[a-z0-9]{4})(?:\.(?:json|csv))?(\?[^#]*)?$/);
    return match ? match[1] + '.csv' + (match[2] || '') : '';
  }
  const srcGet = s => {
    if (!/^https:\/\//.test(s.url || '')) return ' · Request this record from the publisher.';
    const csv = sourceCsv(s.url);
    return (csv ? ` · <a href="${esc(csv)}" target="_blank" rel="noopener noreferrer">download the CSV</a>` : '') +
      (s.got === 'hand' ? ' · Find the saved record by its title in the publisher’s search.' : '');
  };
  function bindRefs(root) {
    root.querySelectorAll('[data-src]').forEach(a => a.addEventListener('click', e => { e.preventDefault(); const el = document.getElementById('src' + a.dataset.src); if (!el) return; document.querySelectorAll('.sources li.hl').forEach(x => x.classList.remove('hl')); el.classList.add('hl'); el.scrollIntoView({ block: 'center' }); }));
  }
  const slugOf = s => String(s).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');

  /* ---------- patterns ---------- */
  function patternsPage(id) {
    const list = id ? C.patterns.filter(p => p.id === id) : C.patterns;
    const data = { 'under-the-line': ['#contracts/line', 'Every contract just under $10M'], 'split-purchase': ['#contracts/split', 'Purchase orders just under the limit, by department'], 'no-bid': ['#contracts/award', 'How nonprofit money was awarded'], 'gift-then-decision': ['#money/gifts', 'Gifts matched to who the department pays'], 'political-loop': ['#money/window', 'Donations inside the contract window'], 'growth-without-controls': ['#orgs?sig=monitoring-repeat', 'Organizations with repeat audit findings'], 'address-cluster': ['#map/layers', 'Address hotspots'] };
    return `${id ? '<p class="small"><a href="#patterns">← All methods</a></p>' : ''}${head('The playbook', id ? esc(list[0]?.name || 'Method') : 'How the schemes work', id ? '' : 'Seventeen recurring methods. Each explains the move in plain words, how to spot it in the records, and what would clear it.')}
      <div class="grid ${id ? '' : 'g2'}">${list.map(p => { const cs = C.cases.filter(c => (c.patterns || []).includes(p.id)); return `<article class="card pattern"><h3>${esc(p.name)} <span class="tag">${cs.length} case${cs.length === 1 ? '' : 's'}</span></h3><p style="margin:0">${esc(p.plain)}</p><dl><dt>How to spot it</dt><dd>${esc(p.spot)}</dd><dt>What would clear it</dt><dd>${esc(p.clear)}</dd></dl>
        ${data[p.id] ? `<p class="small" style="margin:0"><a href="${data[p.id][0]}">Data: ${esc(data[p.id][1])} →</a></p>` : ''}
        ${id ? '' : cs.length ? `<p class="small" style="margin:0"><a href="#pattern/${esc(p.id)}">See the ${cs.length} case${cs.length === 1 ? '' : 's'} →</a></p>` : ''}</article>`; }).join('')}</div>
      ${id ? `<section class="section"><h2>Cases that use it</h2><div class="grid g2">${C.cases.filter(c => (c.patterns || []).includes(id)).map(caseCard).join('') || '<div class="empty">No case file yet.</div>'}</div></section>` : ''}`;
  }

  /* ---------- organizations ---------- */
  function orgsPage(O) {
    const q = S.q.toLowerCase(); let list = O.orgs.filter(o => (!q || (o.name + ' ' + (o.aka || []).join(' ')).toLowerCase().includes(q)) && (!S.sig || o.signals.some(s => s.id === S.sig)));
    const growth = o => (o.fy[2026] || 0) - (o.fy[2022] || 0);
    list = list.slice().sort(S.sort === 'signals' ? (a, b) => b.signals.length - a.signals.length || b.total - a.total : S.sort === 'growth' ? (a, b) => growth(b) - growth(a) : S.sort === 'fy26' ? (a, b) => (b.fy[2026] || 0) - (a.fy[2026] || 0) : (a, b) => b.total - a.total);
    const per = 40, pages = Math.max(1, Math.ceil(list.length / per)); S.page = Math.min(S.page, pages); const rows = list.slice((S.page - 1) * per, S.page * per);
    after.push(() => {
      const f = document.getElementById('of'); f.addEventListener('input', e => { if (e.target.id === 'oq') { S.q = e.target.value; S.page = 1; rerender('oq'); } });
      f.addEventListener('change', e => { if (e.target.id === 'osig') S.sig = e.target.value; if (e.target.id === 'osort') S.sort = e.target.value; S.page = 1; rerender(); });
      main.querySelectorAll('[data-page]').forEach(b => b.addEventListener('click', () => { S.page = +b.dataset.page; rerender(); window.scrollTo(0, 0); }));
    });
    return `${head('Organizations', 'Every nonprofit the City pays, with its warning signs', `${O.orgs.length} organizations that received $1 million or more since fiscal 2019, or that tripped a screen. A warning sign is a reason to look, not a finding.`)}
      <form class="filters" id="of" onsubmit="return false"><input id="oq" type="search" placeholder="Search an organization" value="${esc(S.q)}" aria-label="Search organizations">
        <label>Warning sign <select id="osig"><option value="">Any</option>${Object.entries(SIG).map(([k, v]) => `<option value="${k}" ${S.sig === k ? 'selected' : ''}>${esc(v)}</option>`).join('')}</select></label>
        <label>Sort by <select id="osort">${[['total', 'Total paid'], ['fy26', 'Paid in fiscal 2026'], ['growth', 'Growth since 2022'], ['signals', 'Most warning signs']].map(([k, v]) => `<option value="${k}" ${S.sort === k ? 'selected' : ''}>${v}</option>`).join('')}</select></label></form>
      <p class="muted small">${list.length} organizations · <a href="#screens/insider">Browse by warning sign: insider deals, no-staff structures, standing and audits, federal money, pay →</a></p>
      ${tableOf([{ h: 'Organization', f: o => `<a href="#org/${esc(o.id)}"><b>${esc(o.name)}</b></a>${o.cases.length ? ` <span class="tag">${o.cases.length} case file${o.cases.length > 1 ? 's' : ''}</span>` : ''}<small>${o.signals.map(s => `<span class="sig">${esc(SIG[s.id] || s.id)}</span>`).join('')}${o.signals.length > 4 ? `<span class="sig-more">+ ${o.signals.length - 4} more warning signs</span>` : ''}</small>` }, { h: 'FY2019 → FY2026', f: o => window.FDC.spark(O.years.map(y => o.fy[y] || 0)) }, { h: 'Fiscal 2026', num: 1, f: o => esc(money(o.fy[2026] || 0)) }, { h: 'Total since 2019', num: 1, f: o => esc(money(o.total)) }], rows)}
      <div class="pager"><span>Page ${S.page} of ${pages}</span><span class="row"><button class="btn" data-page="${S.page - 1}" ${S.page <= 1 ? 'disabled' : ''}>← Previous</button><button class="btn" data-page="${S.page + 1}" ${S.page >= pages ? 'disabled' : ''}>Next →</button></span></div>`;
  }
  function orgPage(O, id) {
    const o = O.orgs.find(x => x.id === id); if (!o) return notFound();
    const m = o.method || {}, mt = Object.values(m).reduce((a, b) => a + b, 0), seg = [['nobid', 'No-bid, sole-source or emergency'], ['unrecorded', 'No method recorded'], ['other', 'Other authority'], ['competitive', 'Competitive']].filter(([k]) => m[k] > 0);
    const depts = Object.entries(o.dept || {}).map(([d, ys]) => ({ d, total: Object.values(ys).reduce((a, b) => a + b, 0), last: ys[2026] || 0 })).sort((a, b) => b.total - a.total);
    const x = o.x || {};
    after.push(() => window.FDC.columns(document.getElementById('ofy'), { label: 'City payments by fiscal year', points: O.years.map(y => ({ label: 'FY' + y, short: 'FY' + String(y).slice(2), value: o.fy[y] || 0 })) }));
    const block = (title, body) => body ? `<section class="block"><h2>${title}</h2>${body}</section>` : '';
    return `<p class="small"><a href="#orgs">← All organizations</a></p>${head('Organization', esc(o.name), `${(o.paidGap || {}).words ? `${esc(money(o.paidGap.paid))} in the City’s table of every payment since fiscal 2019 · ${esc(money(o.total))} of it in the City’s nonprofit-spending table (${esc(money(o.fy[2026] || 0))} in fiscal 2026)` : `${esc(money(o.total))} from the City since fiscal 2019 · ${esc(money(o.fy[2026] || 0))} in fiscal 2026`}${(o.aka || []).length ? ` · also paid as ${esc(o.aka.join('; '))}` : ''}`)}
      ${o.cases.length ? `<div class="grid g2" style="margin-bottom:18px">${o.cases.filter(c => byId[c]).map(c => caseCard(byId[c])).join('')}</div>` : ''}
      <div class="card pad"><h3 style="font-size:16px;margin-bottom:10px">Why it is on the list</h3>${o.signals.length ? `<ul class="list">${o.signals.map(s => `<li>${ic('q')}<span><b>${esc(SIG[s.id] || sigName(s.id))}.</b> ${esc(s.text)}${s.h ? ` <a href="${esc(s.h)}">See the records →</a>` : ''}</span></li>`).join('')}</ul>` : '<p class="muted" style="margin:0">No screen tripped. Listed because of the amount paid.</p>'}<p class="small muted" style="margin:12px 0 0">Warning signs are automatic screens on City records. None is a finding.</p></div>
      ${block('Money from the City, by year', `${(o.paidGap || {}).words ? `<p class="card pad small" style="margin-bottom:12px;border-left:3px solid var(--official, #b7791f)"><b>The yearly figures on this page are too low for this organization.</b> They come from the City’s nonprofit-spending table. ${esc(o.paidGap.words)} <a href="#s/two_ledgers.by-organization">See both tables →</a></p>${tableOf([{ h: 'Fiscal year', f: y => 'FY' + y }, { h: 'Nonprofit-spending table (charted below)', num: 1, f: y => esc(money(o.fy[y] || 0)) }, { h: 'Table of every payment', num: 1, f: y => esc(money((o.fyPaid || {})[y] || 0)) }], O.years)}` : (o.ledgerNote || []).length ? `<p class="card pad small" style="margin-bottom:12px;border-left:3px solid var(--official, #b7791f)"><b>This page is too low for this organization.</b> It uses the City’s nonprofit-spending dataset. The City’s table of every payment shows more in ${o.ledgerNote.length === 1 ? 'one year' : o.ledgerNote.length + ' years'}; the latest is fiscal ${esc(o.ledgerNote[o.ledgerNote.length - 1].y)}: ${esc(money(o.ledgerNote[o.ledgerNote.length - 1].t))} against ${esc(money(o.ledgerNote[o.ledgerNote.length - 1].d))} here. The difference is often money passed on to others or premiums. <a href="#s/two_ledgers.by-organization">See both ledgers →</a></p>` : ''}<div class="card pad"><div class="chart" id="ofy"></div></div>${tableOf([{ h: 'Department', f: r => esc(dept(r.d)) + `<small>${esc(r.d)}</small>` }, { h: 'Fiscal 2026', num: 1, f: r => esc(money(r.last)) }, { h: 'Total since 2019', num: 1, f: r => esc(money(r.total)) }], depts)}`)}
      ${mt > 0 ? block('How the money was awarded', `<div class="card pad"><div class="seg" role="img" aria-label="Share of payments by award method">${seg.map(([k], i) => `<div class="s${['nobid', 'unrecorded', 'other', 'competitive'].indexOf(k)}" style="flex:${m[k]}" title="${esc(money(m[k]))}">${m[k] / mt > .09 ? Math.round(m[k] / mt * 100) + '%' : ''}</div>`).join('')}</div><div class="legend" style="border:0;padding:10px 0 0">${seg.map(([k, l]) => `<span><i class="seg" style="width:14px;height:10px"><div class="s${['nobid', 'unrecorded', 'other', 'competitive'].indexOf(k)}" style="flex:1;padding:0"></div></i>${esc(l)} · ${esc(money(m[k]))}</span>`).join('')}</div><p class="small muted" style="margin:10px 0 0">Purchasing authority recorded on each payment, fiscal 2019 onward (DataSF n9pm-xkyq).</p></div>`) : ''}
      ${block('Contracts', `<p class="sub">${o.contracts.n} contracts on record worth ${esc(money(o.contracts.agreedTotal))}; ${o.contracts.soleN} flagged sole-source (${esc(money(o.contracts.soleAgreed))}).</p>${o.contracts.near10M.length ? `<div class="note" style="margin-bottom:12px"><b>${o.contracts.near10M.length} contract${o.contracts.near10M.length > 1 ? 's' : ''} sized between $9.5M and $10M</b> — just under the line that required Board of Supervisors approval. <a href="#contracts/line">See all such contracts →</a></div>` : ''}${tableOf([{ h: 'Contract', f: c => `<b>${esc(c.title || '')}</b><small>${esc(c.no)} · ${esc(dept(c.dept))}${c.sole ? ' · sole source' : ''}</small>` }, { h: 'Term', f: c => `${esc(c.start.slice(0, 7))} → ${esc(c.end.slice(0, 7))}` }, { h: 'Amount', num: 1, f: c => esc(full(c.agreed)) }, { h: 'Paid', num: 1, f: c => esc(money(c.paid)) }], [...o.contracts.near10M, ...o.contracts.largest.filter(c => !o.contracts.near10M.some(n => n.no === c.no))].slice(0, 14))}`)}
      ${Object.keys(o.monitor || {}).length ? block('The City’s own fiscal check-ups', `<div class="card pad"><dl class="kv">${Object.entries(o.monitor).map(([fy, v]) => `<dt>${esc(fy)}</dt><dd>${v.findings} finding${v.findings === 1 ? '' : 's'}; ${v.stillOpen} still open at year end${Object.keys(v.openCategories || {}).length ? ' — ' + esc(Object.keys(v.openCategories).join(', ')) : ''}</dd>`).join('')}</dl><p class="small muted" style="margin:10px 0 0">Controller, Citywide Nonprofit Monitoring (DataSF 3v2z-djjd, 7yeh-dyn4).</p></div>`) : ''}
      ${o.gaveDirect || o.staffGave || o.approvalWindow || o.lobbying || o.behestedReceived ? block('Political money', `<div class="grid g2">
        ${o.gaveDirect ? `<div class="card pad"><h3 style="font-size:16px">It gave ${esc(full(o.gaveDirect.total))} to committees</h3>${tableOf([{ h: 'Date', f: r => esc(fmtDate(r.date)) }, { h: 'Committee', f: r => esc(r.committee) }, { h: 'Amount', num: 1, f: r => esc(full(r.amount)) }], o.gaveDirect.items.slice(-10).reverse())}</div>` : ''}
        ${o.approvalWindow ? `<div class="card pad"><h3 style="font-size:16px">${o.approvalWindow.n} donation${o.approvalWindow.n > 1 ? 's' : ''} by its officers near a contract approval</h3><p class="small muted">${o.approvalWindow.strong} with employer also matching. Name matches need checking.</p>${tableOf([{ h: 'Who → committee', f: r => `${esc(r.person)} <small>${esc(r.role)} → ${esc(r.committee)}</small>` }, { h: 'When', f: r => `${esc(fmtDate(r.contributionDate))}<small>${r.daysFromApproval >= 0 ? r.daysFromApproval + ' days after' : -r.daysFromApproval + ' days before'} approval</small>` }, { h: '$', num: 1, f: r => esc(full(r.amount)) }], o.approvalWindow.items.slice(0, 8))}</div>` : ''}
        ${o.staffGave ? `<div class="card pad"><h3 style="font-size:16px">People listing it as employer gave ${esc(full(o.staffGave.total))}</h3>${tableOf([{ h: 'Committee', f: r => esc(r.committee) + (r.execs.length ? `<small>${esc(r.execs.slice(0, 3).join('; '))}</small>` : '') }, { h: '$', num: 1, f: r => esc(full(r.amount)) }], o.staffGave.top.slice(0, 6))}</div>` : ''}
        ${o.lobbying ? `<div class="card pad"><h3 style="font-size:16px">${o.lobbying.contacts} lobbying contacts on its behalf</h3><p class="small">Most contacted: ${esc(o.lobbying.topOfficials.slice(0, 5).map(x => x[0]).join('; '))}</p><p class="small muted">Subjects: ${esc(o.lobbying.subjects.map(x => x[0]).join(', '))}</p></div>` : ''}</div>`) : ''}
      ${o.giftsToOfficials ? block('Gifts and travel it gave City officials', tableOf([{ h: 'Date', f: g => esc(fmtDate(g.date)) }, { h: 'Official', f: g => `${esc(g.official)}<small>${esc(g.department)}</small>` }, { h: 'What', f: g => esc(g.description || g.kind) }, { h: 'Value', num: 1, f: g => esc(full(g.amount)) }], o.giftsToOfficials.items)) : ''}
      ${x.irs ? block('From its own tax returns', `<div class="card pad"><dl class="kv">${x.irs.map(r => `<dt>${esc(r.k)}</dt><dd>${esc(r.v)}</dd>`).join('')}</dl><p class="small muted" style="margin:10px 0 0">IRS Form 990 e-filings.</p></div>`) : ''}
      ${x.flags ? block('Other records', `<div class="card pad"><ul class="list">${x.flags.map(f => `<li>${ic('q')}<span>${esc(f)}</span></li>`).join('')}</ul></div>`) : ''}
      ${FDY ? FDY.docs(o) : ''}`;
  }

  /* ---------- organization screens ---------- */
  function screensPage(O, tab) {
    tab = tab || 'insider'; const X = O.screens || {}, I = X.irs990_flags || {}, St = X.standing || {}, F = X.federal_flags || {}, Oc = X.outcome_flags || {};
    const tabs = [['insider', 'Deals with insiders'], ['structure', 'No staff, one contractor'], ['standing', 'Standing and audits'], ['federal', 'Federal money too'], ['pay', 'Pay'], ...(Oc.vacancy || Oc.performance ? [['outcomes', 'Results']] : [])];
    const o = r => `<a href="#org/${esc(slugOf(r.key))}"><b>${esc(r.org)}</b></a>`, city = { h: 'City paid, fiscal 2026', num: 1, f: r => esc(money(r.cityFY2026 ?? r.paidFY2026 ?? 0)) }; let body = '';
    if (tab === 'insider') body = `<p class="sub">Nonprofits must tell the IRS when they lend to, borrow from or do business with their own officers, directors, relatives or companies those people own. These are the City-funded organizations that answered yes on their latest return. The question is whether such dealings were fair and board-approved, and whether City money paid for them.</p>
      ${tableOf([{ h: 'Organization', f: r => `${o(r)}<small>return for period ending ${esc(r.period)}</small>` }, { h: 'Disclosed', f: r => esc((r.questions || []).join('; ') || 'Schedule L entries') }, { h: 'Largest items on Schedule L', f: r => (r.items || []).slice(0, 3).map(i => `${esc(i.who)} — ${esc(money(i.amount))}<small>${esc(i.relationship || '')} ${esc(i.what || '')}</small>`).join('') }, city], I.insiderDeals || [])}`;
    else if (tab === 'structure') body = `<p class="sub">Two structures that move a nonprofit’s spending out of sight: reporting no employees at all, and paying most of the budget to a single outside contractor. Both are common for district associations and pass-through foundations; both mean the City’s audit trail ends at a company it has no contract with.</p>
      <h3 style="margin:10px 0 8px">One contractor receives 40% or more of all spending</h3>${tableOf([{ h: 'Organization', f: r => `${o(r)}<small>period ending ${esc(r.period)}</small>` }, { h: 'Contractor', f: r => `<b>${esc(r.contractor)}</b><small>${esc(r.services || '')}</small>` }, { h: 'Paid', num: 1, f: r => esc(money(r.paid)) }, { h: 'Share of spending', num: 1, f: r => Math.round(r.share * 100) + '%' }, city], I.oneVendor || [])}
      <h3 style="margin:26px 0 8px">No employees, $1 million or more in spending</h3>${tableOf([{ h: 'Organization', f: r => `${o(r)}<small>period ending ${esc(r.period)}</small>` }, { h: 'Spending', num: 1, f: r => esc(money(r.expenses)) }, { h: 'Largest contractor', f: r => r.topContractor ? `${esc(r.topContractor)} — ${esc(money(r.topContractorPaid))}` : '<span class="muted">none listed</span>' }, city], I.noStaff || [])}
      <h3 style="margin:26px 0 8px">Contractors paid by three or more City-funded nonprofits</h3>${tableOf([{ h: 'Contractor', f: r => `<b>${esc(r.contractor)}</b>` }, { h: 'Nonprofits', num: 1, f: r => r.n }, { h: 'Paid by', f: r => `<small>${esc(r.orgs.slice(0, 6).map(x => `${x.org} (${money(x.paid)})`).join('; '))}</small>` }], (I.sharedContractors || []).slice(0, 40))}`;
    else if (tab === 'standing') body = `<p class="sub">What regulators and the organizations’ own auditors say, set beside what the City still pays. Matched on federal tax ID only.</p>
      <h3 style="margin:10px 0 8px">State charity registration not current</h3><p class="small muted">California Attorney General “may not operate” list. A charity that is delinquent, suspended or revoked may not solicit or disburse charitable funds.</p>${tableOf([{ h: 'Organization', f: o }, { h: 'Status', f: r => esc(r.status) }, city, { h: 'Total since 2019', num: 1, f: r => esc(money(r.total)) }], St.agNotCurrent || [])}
      <h3 style="margin:26px 0 8px">Federal tax exemption revoked and not reinstated</h3>${tableOf([{ h: 'Organization', f: o }, { h: 'Revoked', f: r => esc(fmtDate(r.date)) }, { h: 'Total since 2019', num: 1, f: r => esc(money(r.total)) }], St.irsRevoked || [])}
      <h3 style="margin:26px 0 8px">On the Controller’s corrective-action list</h3>${tableOf([{ h: 'Organization', f: o }, { h: 'Designation', f: r => esc(r.designations.map(d => `${d.designation} (${d.year})`).join('; ')) }, city, { h: 'Total since 2019', num: 1, f: r => esc(money(r.total)) }], St.tiers || [])}
      <h3 style="margin:26px 0 8px">Its own auditors reported serious control problems</h3><p class="small muted">Federal single audits, 2019–2025: doubt about staying in business, material weakness in financial controls, or material noncompliance.</p>${tableOf([{ h: 'Organization', f: o }, { h: 'Going-concern doubt', f: r => esc(r.goingConcern.join(', ')) }, { h: 'Material weakness', f: r => esc(r.materialWeakness.join(', ')) }, { h: 'Noncompliance', f: r => esc(r.noncompliance.join(', ')) }, city], St.auditWeakness || [])}
      ${(I.missingReturns || []).length ? `<h3 style="margin:26px 0 8px">No tax return found for the two most recent years</h3>${tableOf([{ h: 'Organization', f: o }, { h: 'Latest on file', f: r => esc(r.latestOnFile || 'none') }, city], I.missingReturns)}` : ''}`;
    else if (tab === 'federal') body = `<p class="sub">The same organizations are often paid by federal agencies directly, by the City passing federal money through, and — in 2020–21 — by forgiven federal PPP loans. It matters because a salary reimbursed by a City contract cannot also be covered by a forgiven loan.</p>
      <h3 style="margin:10px 0 8px">Forgiven PPP loans to City-funded nonprofits (${(F.ppp || []).length})</h3><p class="small muted">PPP was for payroll during revenue loss. “City payments rose” marks organizations whose City receipts were at least 10% higher in fiscal 2021 than in 2019.</p>${tableOf([{ h: 'Organization', f: o }, { h: 'PPP loans', num: 1, f: r => esc(money(r.ppp)) }, { h: 'Forgiven', num: 1, f: r => esc(money(r.forgiven)) }, { h: 'City paid FY2019', num: 1, f: r => esc(money(r.cityFY2019)) }, { h: 'City paid FY2021', num: 1, f: r => esc(money(r.cityFY2021)) }, { h: '', f: r => r.cityRose ? '<span class="tag">City payments rose</span>' : '' }], (F.ppp || []).slice(0, 80))}
      <h3 style="margin:26px 0 8px">Also paid directly by federal agencies</h3>${tableOf([{ h: 'Organization', f: o }, { h: 'Direct federal awards, FY2019–26', num: 1, f: r => esc(money(r.federal)) }, { h: 'Federal via the City', num: 1, f: r => esc(money(r.viaCity)) }, { h: 'City total since 2019', num: 1, f: r => esc(money(r.cityTotal)) }, { h: 'Agencies', f: r => `<small>${esc(r.agencies)}</small>` }], (F.directFederal || []).slice(0, 50))}`;
    else if (tab === 'pay') body = `<p class="sub">The highest-paid person at each City-funded nonprofit that reports pay of $350,000 or more, from its latest return. Hospitals and national organizations lead; the right-hand column shows how much of the organization’s revenue is government grants.</p>
      ${tableOf([{ h: 'Organization', f: r => `${o(r)}<small>period ending ${esc(r.period)}</small>` }, { h: 'Person', f: r => `${esc(r.person)}<small>${esc(r.title)}</small>` }, { h: 'Pay', num: 1, f: r => `<b>${esc(money(r.pay))}</b>${r.related ? `<small>+ ${esc(money(r.related))} from related organizations</small>` : ''}` }, { h: 'Government share of revenue', num: 1, f: r => r.govShare == null ? '' : Math.round(r.govShare * 100) + '%' }, city], I.topPay || [])}`;
    else body = `<p class="sub">What the City’s own published records say providers delivered.</p>
      ${(Oc.vacancy || []).length ? `<h3 style="margin:10px 0 8px">Supportive housing sitting empty, by provider</h3>${tableOf([{ h: 'Provider', f: r => r.key ? o(r) : `<b>${esc(r.org)}</b>` }, { h: 'Units', num: 1, f: r => (r.units || 0).toLocaleString() }, { h: 'Vacant', num: 1, f: r => (r.vacant || 0).toLocaleString() }, { h: 'Vacancy', num: 1, f: r => r.rate == null ? '' : (r.rate * 100).toFixed(1) + '%' }, { h: 'As of', f: r => esc(r.asOf || '') }], Oc.vacancy)}` : ''}
      ${(Oc.performance || []).length ? `<h3 style="margin:26px 0 8px">Performance measures missed</h3>${tableOf([{ h: 'Provider', f: r => r.key ? o(r) : `<b>${esc(r.org)}</b>` }, { h: 'Measures reported', num: 1, f: r => r.n }, { h: 'Missed', num: 1, f: r => r.missed }, { h: 'Examples', f: r => `<small>${esc((r.examples || []).join('; '))}</small>` }], Oc.performance)}` : ''}`;
    return `${head('Organizations', 'Warning signs, screen by screen', 'Each list is one test run across every City-funded nonprofit. A row is a reason to look, not a finding; open the organization for the detail and the money.')}
      <nav class="tabs"><a href="#orgs">All organizations</a>${tabs.map(([k, t]) => `<a href="#screens/${k}" ${k === tab ? 'aria-current="page"' : ''}>${t}</a>`).join('')}</nav>${body}`;
  }

  /* ---------- gifts & politics ---------- */
  function moneyPage(L, tab) {
    tab = tab || 'gifts'; const q = S.q.toLowerCase(), has = (...v) => !q || v.join(' ').toLowerCase().includes(q);
    const tabs = [...MONEY_TABS, ...xt('money')];
    after.push(() => { const f = document.getElementById('mf'); if (!f) return; f.addEventListener('input', e => { if (e.target.id === 'mq') { S.q = e.target.value; rerender('mq'); } }); f.addEventListener('change', e => { if (e.target.id === 'mown') { S.own = e.target.checked; rerender(); } }); });
    let body = '';
    if (tab === 'gifts') { const rows = L.gifts.filter(g => (!S.own || g.basis === 'own-department') && has(g.official, g.source, g.department)); body = `<p class="sub">Gifts and paid travel that officials disclosed on Form 700, where the giver was also paid by the official’s own department in the surrounding years. Most are event tickets; the point is to see who gives to whom. It reproduces the one adjudicated case in the data (Supervisor Walton’s trips paid by Bay Area Community Resources).</p>
      <form class="filters" id="mf" onsubmit="return false"><input id="mq" type="search" placeholder="Search an official or giver" value="${esc(S.q)}"><label><input type="checkbox" id="mown" ${S.own ? 'checked' : ''}> Only where the official’s own department pays the giver</label></form><p class="muted small">${rows.length} disclosures</p>
      ${tableOf([{ h: 'Date', f: g => esc(fmtDate(g.date)) }, { h: 'Official', f: g => `<b>${esc(g.official)}</b><small>${esc(g.position || '')} · ${esc(g.department)}</small>` }, { h: 'Giver', f: g => `${esc(g.source)}<small>${esc(g.description)}</small>` }, { h: 'Value', num: 1, f: g => esc(full(g.amount)) }, { h: 'Department paid giver', num: 1, f: g => g.paidByOwnDeptWindow ? esc(money(g.paidByOwnDeptWindow)) + '<small>year before to year after</small>' : `<small>citywide ${esc(money(g.paidCitywideWindow))}</small>` }], rows.slice(0, 300))}`; }
    else if (tab === 'penalties') { const rows = L.penalties.filter(p => has(p.who, p.what)).sort((a, b) => b.date.localeCompare(a.date)); body = `<p class="sub">Every penalty the Ethics Commission has issued. Gift, conflict-of-interest and contractor-contribution cases are the ones that connect to public money.</p><form class="filters" id="mf" onsubmit="return false"><input id="mq" type="search" placeholder="Search a name or violation" value="${esc(S.q)}"></form>
      ${tableOf([{ h: 'Date', f: p => esc(fmtDate(p.date)) }, { h: 'Who', f: p => `<b>${esc(p.who)}</b><small>${esc(p.category || '')}</small>` }, { h: 'Violation', f: p => esc(p.what || '') + (p.url && /^https:/.test(p.url) ? ` <a href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">document ↗</a>` : '') }, { h: 'Penalty', num: 1, f: p => esc(full(p.amount)) }], rows.slice(0, 200))}`; }
    else if (tab === 'window') { const rows = L.window.filter(w => has(w.person, w.contractor, w.committee)); body = `<p class="sub">San Francisco bars a contractor’s officers and directors from giving to an official who must approve its contract (or a candidate for that office) from the start of negotiations until twelve months after approval, for contracts of $100,000 or more (Campaign Code §1.126). These are donations inside a window of 180 days before to 365 days after an approval where the donor’s name matches a listed officer — and, where marked, the donor’s stated employer is the contractor too. Each still needs the approving body, the amount and the negotiation dates checked.</p>
      <form class="filters" id="mf" onsubmit="return false"><input id="mq" type="search" placeholder="Search a person, contractor or committee" value="${esc(S.q)}"></form><p class="muted small">${rows.length} donations</p>
      ${tableOf([{ h: 'Donor', f: w => `<b>${esc(w.person)}</b><small>${esc(w.role)} · ${esc(w.contractor)}${w.employerMatchesContractor ? ' · <b>employer matches</b>' : ' · name match only'}</small>` }, { h: 'Gave to', f: w => esc(w.committee) }, { h: 'Donation', f: w => `${esc(fmtDate(w.contributionDate))}<small>${w.daysFromApproval >= 0 ? w.daysFromApproval + ' days after' : -w.daysFromApproval + ' days before'} approval of ${esc(fmtDate(w.contractDate))}</small>` }, { h: '$', num: 1, f: w => esc(full(w.amount)) }], rows.slice(0, 300))}`; }
    else { const rows = L.ngoDirect.filter(n => has(n.org)); body = `<p class="sub">City-funded nonprofits that themselves gave money to political committees since 2017 — mostly ballot measures, which charities may support within limits. The question is whether public money and political money stay separate.</p><form class="filters" id="mf" onsubmit="return false"><input id="mq" type="search" placeholder="Search an organization" value="${esc(S.q)}"></form>
      ${tableOf([{ h: 'Organization', f: n => `<a href="#org/${esc(slugOrg(n.org))}"><b>${esc(n.org)}</b></a><small>${n.n} contribution${n.n > 1 ? 's' : ''}; largest to ${esc(n.items.slice().sort((a, b) => b.amount - a.amount)[0].committee)}</small>` }, { h: 'Gave', num: 1, f: n => esc(full(n.total)) }, { h: 'City paid it (2019–26)', num: 1, f: n => esc(money(n.cityTotal || 0)) }], rows)}`; }
    return `${head('Gifts & politics', 'Who gives what to whom', 'Four public ledgers, joined: what officials received, what they were fined for, who donated around contract votes, and which grantees fund campaigns.')}
      <nav class="tabs">${tabs.map(([k, t]) => `<a href="#money/${k}" ${k === tab ? 'aria-current="page"' : ''}>${t}</a>`).join('')}</nav>${body}`;
  }
  const slugOrg = name => slugOf(name.toUpperCase().replace(/&/g, ' AND ').replace(/[^A-Z0-9 ]/g, ' ').replace(/\b(INC|INCORPORATED|LLC|LLP|LP|CORP|CORPORATION|CO|COMPANY|THE|OF|AND|FOR|A CALIFORNIA|DBA)\b/g, ' ').replace(/\bS F\b|\bSF\b/g, 'SAN FRANCISCO').replace(/\bSVCS\b/g, 'SERVICES').replace(/\bCTR\b/g, 'CENTER').replace(/\bFNDTN\b|\bFDN\b/g, 'FOUNDATION').replace(/\bCOMM\b/g, 'COMMUNITY'));

  /* ---------- contracts & purchasing ---------- */
  function contractsPage(L, tab) {
    tab = tab || 'line'; const st = C.stats, tabs = [...CONTRACT_TABS, ...xt('contracts')]; let body = '';
    if (tab === 'line') {
      after.push(() => window.FDC.histogram(document.getElementById('h10'), { label: 'Number of contracts by size, $7M to $13M', bins: st.line10M.histogram, line: 1e7, lineLabel: '$10M historical spending threshold' }));
      body = `<p class="sub">The Charter required Board approval for covered nonconstruction agreements with anticipated net spending of $10 million or more. The term and amendment rules could also trigger review. The November 2026 vote did not itself change those thresholds. <a href="https://media.api.sf.gov/documents/Memo_re_Impacts_of_Charter_Amendments_in_Propositions_A_E_and_F.pdf" target="_blank" rel="noopener noreferrer">City Attorney’s transition guidance, pages 1 and 11</a>. Of ${st.contracts.toLocaleString()} City contracts on record, ${st.line10M.justBelow_9_5_to_10} sit between $9.5M and $10M and only ${st.line10M.justAbove_10_to_10_5} between $10M and $10.5M. ${st.line10M.within1k} are within $1,000 of the line; ${st.line10M.exact_9999999} are exactly $9,999,999.</p>
        <div class="grid g4" style="margin-bottom:16px">${stat(String(st.line10M.justBelow_9_5_to_10), 'contracts $9.5M – $10M')}${stat(String(st.line10M.justAbove_10_to_10_5), 'contracts $10M – $10.5M')}${stat(String(st.line10M.within1k), 'within $1,000 of the line')}${stat(String(st.line10M.belowNonprofit), 'of those just below are with nonprofits')}</div>
        ${chartBox('h10', 'Contracts pile up just before the line', 'One row per contract number; team allocations summed. Source: Controller, Supplier Contracts (DataSF cqi5-hm2d).')}
        <div class="note" style="margin:16px 0">What matters is what happened next: was it amended past the line, and was the Board asked before or after the money was committed? ${byId['under-ten-million-then-amended'] ? '<a href="#case/under-ten-million-then-amended">Read the case with the amendment histories →</a>' : ''}</div>
        <h3 style="margin:22px 0 8px">The ${L.contracts.razor.length} contracts within $10,000 of the line</h3>
        ${tableOf([{ h: 'Amount', num: 1, f: c => `<b>${esc(full(c.agreed))}</b>` }, { h: 'Supplier', f: c => `${esc(c.supplier)}<small>${esc(c.title || '')} · ${esc(c.no)}</small>` }, { h: 'Department', f: c => esc(dept(c.dept)) }, { h: 'Term', f: c => `${esc(c.start.slice(0, 7))} → ${esc(c.end.slice(0, 7))}` }, { h: 'Paid so far', num: 1, f: c => esc(money(c.paid)) }, { h: '', f: c => `${c.nonprofit ? '<span class="tag">nonprofit</span>' : ''} ${c.sole ? '<span class="tag">sole source</span>' : ''}` }], L.contracts.razor)}`;
    } else if (tab === 'split') {
      const sp = L.split, strips = sp.strips || [], s = strips[Math.min(S.strip, strips.length - 1)];
      after.push(() => {
        window.FDC.ranked(document.getElementById('sdept'), { label: 'Share of small no-bid purchase orders that sit within 10% of the limit, by department', fmt: v => Math.round(v * 100) + '%', labelW: 250, rows: sp.departments.slice(0, 14).map(d => ({ label: dept(d.dept), value: d.shareJustUnder, sub: `${d.posJustUnder} of ${d.posHalfToLimit} orders`, cls: d.dept === 'HRC' ? '' : 'de' })) });
        if (s) window.FDC.strip(document.getElementById('sstrip'), { label: 'Purchase orders by date and amount', orders: s.orders });
        document.getElementById('ssel')?.addEventListener('change', e => { S.strip = +e.target.value; rerender(); });
      });
      body = `<p class="sub">Departments may buy without bidding or outside approval up to a limit: $10,000 through June 2024, $20,000 since. Splitting one purchase into several to stay under it is prohibited. In 2025 the Controller found the Human Rights Commission had done exactly that. This measures the same footprint everywhere: of each department’s no-bid orders between half the limit and the limit, how many sit in the top 10%.</p>
        ${chartBox('sdept', 'Share of orders sized within 10% of the limit', `Citywide: ${Math.round(sp.departments.length ? C.stats.split.citywide.shareJustUnder * 100 : 0)}%. The Human Rights Commission is highlighted. Source: Controller, purchase-order summary (DataSF p5r5-fd7g), fiscal 2019 onward.`)}
        <div class="card pad" style="margin-top:16px"><div class="chart-h"><h3>Every order to one supplier</h3><select id="ssel" aria-label="Supplier">${strips.map((x, i) => `<option value="${i}" ${i === S.strip ? 'selected' : ''}>${esc(dept(x.dept))} — ${esc(x.vendor)} (${x.justUnder} just under)</option>`).join('')}</select></div><p class="small muted">Each dot is one purchase order. Blue dots are within 10% under the limit in force that day. Watch what happens to the order sizes when the limit doubles.</p><div class="chart" id="sstrip"></div>${s && s.topVendors ? `<p class="small" style="margin:10px 0 0">Suppliers with the most just-under orders: ${esc(s.topVendors.slice(0, 8).map(v => `${v[0]} (${v[1]})`).join('; '))}</p>` : ''}</div>
        <div class="note" style="margin:16px 0">A cluster is a reason to pull the invoices, not proof. Many separate small jobs — a repair shop’s work orders, monthly rentals — look the same in this data. Order dates are as recorded by the City and some orders were re-dated later, so read the chart for sizes, not for exact days. ${byId['purchase-limit-beyond-hrc'] ? '<a href="#case/purchase-limit-beyond-hrc">Read the case →</a>' : ''}</div>
        <h3 style="margin:22px 0 8px">Densest clusters: one department, one supplier, one year</h3>
        ${tableOf([{ h: 'Department', f: c => esc(dept(c.dept)) }, { h: 'Supplier', f: c => `<b>${esc(c.vendor)}</b>${c.nonprofit ? ' <span class="tag">nonprofit</span>' : ''}` }, { h: 'Year', f: c => 'FY' + c.fy }, { h: 'Orders just under limit', num: 1, f: c => c.posJustUnder }, { h: 'Paid on those orders', num: 1, f: c => esc(money(c.paid)) }], sp.clusters.slice(0, 60))}`;
    } else {
      const m = st.awardMethod, mt = Object.values(m).reduce((a, b) => a + b, 0) || 1, order = [['nobid', 'No-bid, sole-source or emergency'], ['unrecorded', 'No method recorded'], ['other', 'Other authority (mostly “authorized by grant”)'], ['competitive', 'Competitive solicitation']];
      const aw = st.award;
      if (aw) after.push(() => window.FDC.columns(document.getElementById('nby'), { label: 'No-bid payments to nonprofits by fiscal year', points: aw.years.map(y => ({ label: 'FY' + y, short: 'FY' + String(y).slice(2), value: aw.noBidByYear[y] || 0, note: `emergency ${money(aw.byYear.emergency[y] || 0)}, standing waiver ${money(aw.byYear.waiver[y] || 0)}, sole source ${money(aw.byYear.sole[y] || 0)}` })) }));
      body = `<p class="sub">Each payment to a nonprofit records the purchasing authority it was made under. Since fiscal 2019, ${esc(money(m.nobid || 0))} went out under authorities that skip competition: emergency declarations, sole-source waivers and standing waivers for homelessness and behavioral-health services.</p>
        <div class="card pad"><div class="chart-h"><h3>Payments to nonprofits by how the contract was awarded, fiscal 2019 to date</h3></div><div class="seg" role="img" aria-label="Payments by award method">${order.map(([k], i) => `<div class="s${i}" style="flex:${m[k] || 0}">${Math.round((m[k] || 0) / mt * 100)}%</div>`).join('')}</div><div class="legend" style="border:0;padding:12px 0 0">${order.map(([k, l], i) => `<span><i class="seg" style="width:14px;height:10px"><div class="s${i}" style="flex:1;padding:0"></div></i>${esc(l)} · <b>${esc(money(m[k] || 0))}</b></span>`).join('')}</div><p class="small muted" style="margin:10px 0 0">Source: Controller, vendor payments (DataSF n9pm-xkyq), nonprofit suppliers.</p></div>
        ${aw ? `<div style="margin-top:16px">${chartBox('nby', 'No-bid payments to nonprofits, by fiscal year', 'Emergency authority peaked in fiscal 2023; a standing waiver for homelessness and behavioral-health services has since replaced it and grown past it. Hover a column for the split.')}</div>
        <h3 style="margin:22px 0 8px">Who received the most without competition</h3>${tableOf([{ h: 'Organization', f: r => `<a href="#org/${esc(slugOrg(r.vendor))}"><b>${esc(r.vendor)}</b></a>` }, { h: 'Emergency', num: 1, f: r => esc(money(r.emergency || 0)) }, { h: 'Standing waiver', num: 1, f: r => esc(money(r.waiver || 0)) }, { h: 'Sole source', num: 1, f: r => esc(money(r.sole || 0)) }, { h: 'Total no-bid', num: 1, f: r => `<b>${esc(money(r.total))}</b>` }], aw.topNoBid.slice(0, 25))}` : ''}
        <div class="note" style="margin:16px 0">The Board itself passed ordinances waiving competition for homelessness services. The risk is that nobody tests the price or the choice of provider. <a href="#orgs?sig=nobid">Organizations paid mostly without competition →</a></div>`;
    }
    return `${head('Contracts & purchasing', 'Where the rules bend', 'Three places the City’s spending controls are most often side-stepped — measured across every department, not just the ones already caught.')}<nav class="tabs">${tabs.map(([k, t]) => `<a href="#contracts/${k}" ${k === tab ? 'aria-current="page"' : ''}>${t}</a>`).join('')}</nav>${body}`;
  }

  /* ---------- map ---------- */
  function mapPage(M) {
    const layers = M.layers, li = Math.min(+S.tab || 0, layers.length - 1), layer = layers[li];
    after.push(() => {
      const show = i => { const p = layer.points[i], d = document.getElementById('mapd'); d.innerHTML = `<h3 style="font-size:17px;margin-bottom:6px">${esc(p.title)}</h3><p class="small muted">${esc(p.sub || '')}</p>${p.items ? `<ul class="list">${p.items.slice(0, 40).map(x => `<li>${ic('arrow')}<span>${esc(x)}</span></li>`).join('')}</ul>` : ''}`; };
      window.FDC.map(document.getElementById('mapsvg'), M.geo, layer.points.map((p, i) => ({ x: p.x, y: p.y, v: p.v, i, t: `<b>${esc(p.title)}</b>${esc(p.sub || '')}` })), show);
      document.getElementById('mlayer')?.addEventListener('change', e => { S.tab = e.target.value; rerender(); });
    });
    return `${head('Map', 'Where the money lands', 'Where public money lands and where look-alike businesses crowd one address. A cluster is a place to look, not a conclusion — big office buildings and shared workspaces are full of unrelated tenants.')}${FDX && FDX.mapTabs && M.flagged ? FDX.mapTabs('layers') : ''}
      <form class="filters" onsubmit="return false"><label>Show <select id="mlayer">${layers.map((l, i) => `<option value="${i}" ${i === li ? 'selected' : ''}>${esc(l.name)}</option>`).join('')}</select></label></form><p class="sub">${esc(layer.about || '')}</p>
      <div class="case-layout"><div class="card pad map"><div id="mapsvg"></div></div><aside class="rail"><div class="card pad" id="mapd"><p class="muted" style="margin:0">Select a circle to see who is there.</p></div></aside></div>
      ${M.screens ? `<section class="section"><h2>Business-registration screens</h2><p class="sub">${M.screens.matchedSuppliers.toLocaleString()} City suppliers were matched by name to a San Francisco business registration. Name matching misses and mis-hits; each row is a question to check, not a finding.</p>
        <div class="cols2"><div class="card pad"><h3 style="font-size:16px;margin-bottom:4px">New entity, large money fast</h3><p class="small muted">Registered in 2019 or later and paid $1 million or more within two fiscal years of registering.</p>${tableOf([{ h: 'Supplier', f: r => `<b>${esc(r.supplier)}</b>${r.nonprofit ? ' <span class="tag">nonprofit</span>' : ''}<small>${esc(r.address)}</small>` }, { h: 'Registered', f: r => esc(fmtDate(r.firstRegistered)) }, { h: 'Paid within two years', num: 1, f: r => esc(money(r.paidWithinTwoFiscalYears)) }], M.screens.largePaymentsSoonAfterRegistering.slice(0, 30))}</div>
        <div class="card pad"><h3 style="font-size:16px;margin-bottom:4px">Paid after the registration ended</h3><p class="small muted">Every matching registration shows an end date, yet payments continued in later fiscal years. Often a re-registration under another name — check first.</p>${tableOf([{ h: 'Supplier', f: r => `<b>${esc(r.supplier)}</b>${r.nonprofit ? ' <span class="tag">nonprofit</span>' : ''}<small>${esc(r.address)}</small>` }, { h: 'Registration ended', f: r => esc(fmtDate(r.lastRegistrationEnded)) }, { h: 'Paid afterwards', num: 1, f: r => esc(money(r.paidInLaterFiscalYears)) }], M.screens.paidAfterRegistrationEnded.slice(0, 30))}</div></div></section>` : ''}
      <h3 style="margin:26px 0 8px">Largest in this view</h3>${tableOf([{ h: 'Address', f: p => `<b>${esc(p.title)}</b><small>${esc(p.sub || '')}</small>` }, { h: layer.unit || 'Count', num: 1, f: p => esc(layer.money ? money(p.v) : p.v.toLocaleString()) }], layer.points.slice().sort((a, b) => b.v - a.v).slice(0, 40))}`;
  }

  /* ---------- health billing ---------- */
  function healthPage(Hh, tab) {
    tab = tab || 'clusters'; const tabs = [['clusters', 'Many billing numbers, one address'], ['agencies', 'Hospice and home-health surges'], ['outliers', 'Billing far above peers'], ['sanctioned', 'Sanctioned but still enrolled'], ['owners', 'One owner, many agencies']]; let body = '';
    const cat = c => Object.entries(c.categories).map(([k, v]) => `${v} ${k.replace(/_/g, ' ')}`).join(', ');
    if (tab === 'clusters') {
      const fresh = Hh.clusters.filter(c => c.allNew), sf = Hh.clusters.filter(c => c.county === 'San Francisco' && !c.allNew).slice(0, 40);
      const cols = [{ h: 'Address', f: c => `<b>${esc(c.address)}</b><small>${esc(c.city)} · ${esc(c.county)} County</small>` }, { h: 'Billing entities', f: c => `<b>${c.billingTypeEntities}</b> equipment, lab, hospice or home-health<small>${esc(cat(c))} · ${c.orgNumbers} organizational numbers in all</small>` }, { h: 'Registered', f: c => `${esc(fmtDate(c.first))} → ${esc(fmtDate(c.last))}` }, { h: 'Names', f: c => `<small>${esc(c.names.slice(0, 6).join('; '))}${c.names.length > 6 ? '…' : ''}</small>` }];
      body = `<p class="sub">Anyone can obtain a federal provider number online in minutes, and nobody inspects the address. Phantom-billing schemes exploit that by registering many equipment suppliers and laboratories at one place. This lists Bay Area addresses with several such entities — first the ones where every entity is new.</p>
        ${byId['one-apartment-62-billing-numbers'] ? `<div class="grid g2" style="margin-bottom:18px">${caseCard(byId['one-apartment-62-billing-numbers'])}</div>` : ''}
        <h3 style="margin:8px 0">Every entity registered in the last two years (${fresh.length})</h3>${tableOf(cols, fresh)}
        <h3 style="margin:26px 0 8px">San Francisco addresses with the most billing entities</h3><p class="small muted">Mostly hospitals and medical office buildings — listed so the unusual ones stand out.</p>${tableOf(cols, sf)}`;
    } else if (tab === 'agencies') {
      body = `<p class="sub">Hospice and home-health agencies in the Bay Area whose Medicare payments grew at least fourfold within four years, or that were licensed since 2020 and already receive $1 million or more a year. Fast growth is the profile auditors screen for; it is not evidence of wrongdoing.</p>
        ${byId['bay-area-hospice-surge'] ? `<div class="grid g2" style="margin-bottom:18px">${caseCard(byId['bay-area-hospice-surge'])}</div>` : ''}
        ${tableOf([{ h: 'Agency', f: x => `<b>${esc(x.name)}</b><small>${esc(x.type.replace('_', ' '))} · ${esc(x.where)}</small>` }, { h: '2018 → 2024', f: x => window.FDC.spark(x.series.map(p => p.value)) }, { h: 'First year', num: 1, f: x => `${esc(money(x.paidFirst))}<small>${x.firstYear}</small>` }, { h: 'Latest year', num: 1, f: x => `<b>${esc(money(x.paidLast))}</b><small>${x.lastYear} · ${x.patientsLast} patients</small>` }, { h: 'Growth', num: 1, f: x => x.growth ? x.growth + '×' : '' }], Hh.agencies)}`;
    } else if (tab === 'outliers') {
      after.push(() => window.FDC.columns(document.getElementById('hpb'), { label: 'Medicare Part B payments to San Francisco providers', points: Object.entries(Hh.sfPartBByYear).map(([y, v]) => ({ label: y, value: v })) }));
      body = `<p class="sub">Medicare Part B paid ${esc(money(Hh.sfPartBByYear[Hh.latestBillingYear]))} to ${Hh.providersLatest.toLocaleString()} San Francisco providers in ${Hh.latestBillingYear}. These are the ones paid at least five times the national median per patient for their own specialty, or whose payments more than tripled in a year. Laboratories headquartered here bill for patients nationwide, which explains some of the largest.</p>
        ${chartBox('hpb', 'Medicare Part B payments to San Francisco providers, by year')}
        <h3 style="margin:22px 0 8px">Outliers, ${Hh.latestBillingYear}</h3>${tableOf([{ h: 'Provider', f: x => `<b>${esc(x.who)}</b><small>${esc(x.type)} · ZIP ${esc(x.zip)}</small>` }, { h: 'Medicare paid', num: 1, f: x => esc(money(x.paid)) }, { h: 'Patients', num: 1, f: x => x.patients.toLocaleString() }, { h: 'Per patient', num: 1, f: x => `${esc(money(x.perPatient))}<small>peers ${esc(money(x.peerMedian))}</small>` }, { h: 'Times peer median', num: 1, f: x => `<b>${x.ratio}×</b>` }, { h: 'Change in a year', num: 1, f: x => x.yoyPct == null ? '' : (x.yoyPct > 0 ? '+' : '') + x.yoyPct + '%' }], Hh.outliers)}`;
    } else if (tab === 'sanctioned') {
      body = `<p class="sub">Providers on Medicare’s revoked list or Medi-Cal’s suspended list — matched on the exact provider number — that still appear as enrolled in the other program, or billed in San Francisco after the sanction date. Being barred from one program does not automatically end enrolment in the other.</p>
        ${tableOf([{ h: 'Provider', f: x => `<b>${esc(x.who)}</b><small>${esc(x.type)} · ${esc(x.where)}</small>` }, { h: 'Sanction', f: x => `${esc(x.list)}<small>${esc(x.reason)}</small>` }, { h: 'Date', f: x => `${esc(x.date)}<small>${esc(x.until)}</small>` }, { h: 'Still listed in', f: x => [x.stillMedicare ? 'Medicare enrollment' : '', x.stillMediCal ? 'Medi-Cal provider file' : '', x.lastSFBilling ? 'billed in SF ' + x.lastSFBilling : ''].filter(Boolean).join('; ') }], Hh.sanctioned)}`;
    } else {
      body = `<p class="sub">Owners and managing companies recorded on four or more Medicare-enrolled nursing homes, hospices, home-health agencies or equipment suppliers with a Bay Area presence. The list shows who to look at when one facility has problems.</p>
        ${tableOf([{ h: 'Owner', f: x => `<b>${esc(x.owner)}</b><small>${esc(x.types.join(', '))}</small>` }, { h: 'Agencies', num: 1, f: x => x.n }, { h: 'Examples', f: x => `<small>${esc(x.agencies.slice(0, 5).map(a => `${a.name} (${a.city})`).join('; '))}</small>` }], Hh.owners)}`;
    }
    return `${head('Health billing', 'Medicare and Medi-Cal: where the billing looks wrong', 'Public federal and state health-payment records for San Francisco and the Bay Area, screened for the patterns investigators look for. These are private providers billing public insurance — separate from City contracts.')}<nav class="tabs">${tabs.map(([k, t]) => `<a href="#health/${k}" ${k === tab ? 'aria-current="page"' : ''}>${t}</a>`).join('')}</nav>${body}`;
  }

  /* ---------- people index, search, method ---------- */
  function whoPage(k) {
    const w = C.who[k]; if (!w) return notFound();
    return `${head(w.type === 'person' ? 'Person' : 'Organization', esc(w.name), `Appears in ${w.cases.length} case file${w.cases.length > 1 ? 's' : ''}.`)}<div class="grid g2">${w.cases.filter(x => byId[x.id]).map(x => caseCard(byId[x.id])).join('')}</div>
      <section class="section"><h2>Role in each</h2>${tableOf([{ h: 'Case', f: x => `<a href="#case/${esc(x.id)}">${esc(byId[x.id].title)}</a>` }, { h: 'Role', f: x => esc(x.role) }, { h: 'Evidence', f: x => tier(byId[x.id].tier) }], w.cases)}</section>`;
  }
  function connectionsPage() {
    const multi = Object.entries(C.who).filter(([, w]) => w.cases.length > 1).sort((a, b) => b[1].cases.length - a[1].cases.length);
    return `${head('Connections', 'The names that recur', 'People and organizations that appear in more than one case file. Appearing in a case is not an accusation — agencies and bystanders recur too.')}
      ${tableOf([{ h: 'Name', f: ([k, w]) => `<a href="#who/${esc(k)}"><b>${esc(w.name)}</b></a><small>${esc(w.type)}</small>` }, { h: 'Cases', f: ([, w]) => w.cases.filter(x => byId[x.id]).map(x => `<a class="chip" href="#case/${esc(x.id)}">${esc(byId[x.id].title.slice(0, 44))}${byId[x.id].title.length > 44 ? '…' : ''}</a>`).join(' ') }], multi)}`;
  }
  function searchPage(O) {
    const q = S.q.toLowerCase(); if (!q) return head('Search', 'Search everything', 'Type a name in the box above.');
    const cs = C.cases.filter(c => JSON.stringify([c.title, c.oneLine, c.story, c.actors.map(a => a.name)]).toLowerCase().includes(q)), os = O.orgs.filter(o => (o.name + ' ' + (o.aka || []).join(' ')).toLowerCase().includes(q)).slice(0, 30), ws = Object.entries(C.who).filter(([, w]) => w.name.toLowerCase().includes(q)).slice(0, 30);
    const seen = new Set(), ps = !FDY ? [] : C.desks.flatMap(d => [['topic/' + d.id, d.title, d.blurb, 'Topic'], ...d.pages.map(p => [p[0], p[1], p[2], d.title])]).filter(p => (p[1] + ' ' + p[2]).toLowerCase().includes(q) && !seen.has(p[0]) && seen.add(p[0])).slice(0, 24);
    return `${head('Search', `Results for “${esc(S.q)}”`, `${cs.length} case files · ${ps.length} pages of records · ${os.length} organizations · ${ws.length} names`)}
      ${ps.length ? `<section class="section" id="sr-pages"><h2>Pages of records</h2><ol class="page-list">${ps.map(p => `<li><a href="#${esc(p[0])}"><b>${esc(p[1])}</b><span><span class="tag">${esc(p[3])}</span> ${esc(p[2])}</span></a></li>`).join('')}</ol></section>` : ''}
      ${cs.length ? `<div class="grid g2">${cs.map(caseCard).join('')}</div>` : ''}
      ${ws.length ? `<section class="section"><h2>Names in case files</h2><div class="row">${ws.map(([k, w]) => `<a class="chip" href="#who/${esc(k)}">${esc(w.name)} · ${w.cases.length}</a>`).join('')}</div></section>` : ''}
      ${os.length ? `<section class="section"><h2>Organizations</h2>${tableOf([{ h: 'Organization', f: o => `<a href="#org/${esc(o.id)}"><b>${esc(o.name)}</b></a>` }, { h: 'Total since 2019', num: 1, f: o => esc(money(o.total)) }], os)}</section>` : ''}
      ${!cs.length && !os.length && !ws.length && !ps.length ? '<div class="empty">Nothing found. Try a shorter name.</div>' : ''}`;
  }
  function methodPage(tab) {
    if (tab !== 'data') tab = '';
    return `${head('Method and data', 'How this was built', 'What each evidence label means and where every number comes from.')}
      <nav class="tabs">${[['', 'Evidence labels'], ['data', 'Data sources']].map(([k, t]) => `<a href="#method${k ? '/' + k : ''}" ${(tab || '') === k ? 'aria-current="page"' : ''}>${t}</a>`).join('')}</nav>
      ${!tab ? `<div class="grid g2">${['PROVEN', 'CHARGED', 'OFFICIAL', 'REDFLAG', 'CLEARED'].map(t => `<div class="card pad bar-${t}" style="border-left:5px solid var(--t)">${tier(t, true)}<p style="margin:10px 0 0">${esc(TIER[t].help)}</p></div>`).join('')}</div>
        <section class="section"><h2>Rules we hold to</h2><div class="card pad"><ul class="list">${['Case findings cite the records used. Each entry identifies the publisher and, where available, the document or dataset.', 'A number always says what it measures. Payments, contract ceilings, alleged losses and penalties are never added together.', 'Connected organizations do not mean the same dollars moved along the chain.', 'A shared name, address or board seat is a lead to check, never proof.', 'A fiscal-year label and a voucher issue date can differ. Each payment analysis identifies which measure it uses. A database refresh date describes the dataset.', 'Each lead states what the records do not show and the record that would settle it.', 'The older file data.json (October 2026) is not used for any number here.'].map(x => `<li>${ic('check')}<span>${esc(x)}</span></li>`).join('')}</ul></div></section>` : ''}
      ${tab === 'data' ? `<div class="note how"><p><b>This site does not host the raw data.</b> Everything here was pulled ${esc(pulledSpan())} from public sources, and every source on the site links to the place you can view or download it yourself: the City’s open-data portal (DataSF), the Board of Supervisors’ legislative record (Legistar), the Ethics Commission’s filings, IRS returns, federal and State datasets, court dockets and published reports. On a case page, each numbered source links to the original; a DataSF dataset also has a link to download it as a CSV file.</p><p>A few records were obtained by a public records request or saved by hand from a site that does not allow automated download. Those sources link to the agency’s own search page or say “Not online”, with the agency to ask. Records the project asked for and could not get are listed under <a href="#wanted">Requested data</a>, with how to ask for each one.</p></div>
        ${C.sourceReview?.unique ? `<section class="section"><h2>Case citation check</h2><p class="sub">On ${esc(fmtDate(C.sourceReview.asOf))}, the ${C.sourceReview.citations.toLocaleString('en-US')} source entries across ${C.sourceReview.cases.toLocaleString('en-US')} cases pointed to ${C.sourceReview.unique.toLocaleString('en-US')} distinct public addresses. Automated requests reached ${C.sourceReview.reachable.toLocaleString('en-US')}. Of the others, ${C.sourceReview.forbidden.toLocaleString('en-US')} returned an access restriction. Some archives require a browser or a record search. This check measures link availability. Use the cited document, reporting period and case notes to verify the finding itself.</p></section>` : ''}
        ${C.sourceReview?.archiveReview ? `<section class="section"><h2>What the archive review covered</h2><p class="sub">The content scan began with ${C.sourceReview.archiveReview.initialFiles.toLocaleString('en-US')} files, including the owner-supplied collections and extracted copies. It read ${C.sourceReview.archiveReview.rows.toLocaleString('en-US')} rows in standalone tables. A separate pass examined ${C.sourceReview.archiveReview.sheets.toLocaleString('en-US')} worksheet rows. These counts can overlap across copies. Optical character recognition covered all 25,385 pages in the scan index. The evidence review describes damaged files, recovered originals and remaining gaps. Case pages cite the records used for each finding. <a href="EVIDENCE_REVIEW.md" download>Download the evidence review</a>.</p></section>` : ''}
        <section class="section"><h2>What did the rail budgets deliver?</h2><p class="sub"><a href="#s/bart_operations">BART spending, riders and service hours</a> compares budgets with actuals and federal service data. <a href="#s/caltrain_operations">Caltrain budgets, ridership and project delivery</a> tracks passenger fares and individual project milestones.</p></section>
        <section class="section"><h2>How long did public work take?</h2><p class="sub"><a href="#permit-time">Look up a permit by number</a> or download the complete timeline register. <a href="#s/permit_metrics">Building permit review times</a> show which review stations take longest. <a href="#s/delivery_time">Capital project completion times</a> compare bond components with their original schedules. View reported completions and projections separately, or <a href="assets/data/bond-completion-dates.json" download>download all 83 bond components and dates</a>.</p></section>
        <section class="section"><h2>Which rules applied on the decision date?</h2><p class="sub">The 2014 HealthRIGHT360 review uses the law and budget in the signed resolution. Six months of actual expenses, the remaining budget and a 12% contingency on that remaining budget add to the approved $62,797,796 ceiling. For the November 2026 Charter amendment, the City Attorney tied the effective date to state acceptance after the Board declares the results. The election alone did not change the approval threshold.</p><p><a href="https://sfgov.legistar.com/View.ashx?M=F&amp;ID=3184657&amp;GUID=EC33BB48-DEBF-4BBE-AE1E-A636AAF177BF">2014 analyst’s budget, pages 44–46</a> · <a href="https://sfbos.org/ftp/uploadedfiles/bdsupvrs/resolutions14/r0304-14.pdf">Signed 2014 resolution</a> · <a href="https://media.api.sf.gov/documents/Memo_re_Impacts_of_Charter_Amendments_in_Propositions_A_E_and_F.pdf">November 2026 City Attorney memo, pages 1 and 11</a></p></section>
        <h3 style="margin:24px 0 8px">City datasets used</h3>${tableOf([{ h: 'Dataset', f: m => `<a href="${esc(m.portal)}" target="_blank" rel="noopener noreferrer"><b>${esc(m.officialName || m.dataset)}</b> ↗</a><small>${esc(m.why || '')}</small>` }, { h: 'Rows', num: 1, f: m => (m.rows || 0).toLocaleString() }, { h: 'Source updated', f: m => esc(m.portalRowsUpdated || '') }, { h: 'Download', f: m => dsId(m.portal) ? `<a href="${esc(csvUrl(dsId(m.portal)))}" target="_blank" rel="noopener noreferrer">CSV ↓</a>` : '' }], C.manifest)}
        <h3 style="margin:24px 0 8px">Other collections</h3><p class="sub">These collections include downloaded records and supporting files. Use the links on an individual case to find the document, query or registry identifier behind a finding.</p>${tableOf([{ h: 'Collection', f: e => `<b>${esc(e.title || e.folder)}</b>` }, { h: 'Downloaded from', f: e => (e.from || []).length ? e.from.map(h => `<a href="${esc(h.u)}" target="_blank" rel="noopener noreferrer">${esc(h.t)}</a>`).join(', ') : 'Several public sites; see the sources on each page' }, { h: 'Files', num: 1, f: e => e.files.toLocaleString() }, { h: 'Size', num: 1, f: e => e.mb.toLocaleString() + ' MB' }], C.extraData)}` : ''}
      <section class="section"><p class="small muted">Built ${esc(C.built)}.</p></section>`;
  }
  const notFound = () => `${head('Not found', 'That page does not exist', '')}<a class="btn" href="#">Back to the films</a>`;

  function permitTimePage(initialId) {
    const id = String(initialId || '').trim().toUpperCase();
    const path = 'assets/data/permit-duration/';
    const reasons = {
      issued: 'The register records a filing date and a subsequent or same-day issuance.',
      open: 'The permit was still listed with an active pre-issuance status at the snapshot.',
      ended: 'The register shows a closed status without a comparable issuance date.',
      other: 'The recorded status and dates do not support an issuance interval or an open-application age.',
      filing_missing: 'The record has no usable filing date.',
      sequence: 'The recorded dates are out of sequence.',
      open_inconsistent: 'The status and milestone dates disagree.'
    };
    const day = value => value == null ? 'Unrecorded' : new Date(value * 86400000).toISOString().slice(0, 10);
    const interval = value => value == null ? 'Unavailable' : value.toLocaleString('en-US') + (value === 1 ? ' day' : ' days');
    after.push(() => {
      const form = document.getElementById('permit-time-form'), result = document.getElementById('permit-time-result');
      form.addEventListener('submit', event => {
        event.preventDefault();
        const entered = form.elements.permit.value.trim().toUpperCase();
        if (entered) location.hash = 'permit-time/' + encodeURIComponent(entered);
      });
      if (!id) return;
      if (!/^[A-Z0-9]{2,12}$/.test(id)) {
        result.textContent = 'Enter the permit number as printed, including any leading zeroes.';
        return;
      }
      const read = async file => {
        const response = await fetch(path + file);
        if (!response.ok) throw new Error('Download failed');
        return response.json();
      };
      let bucket = 0;
      for (const char of id) bucket = (31 * bucket + char.charCodeAt(0)) & 255;
      result.textContent = 'Looking up this permit…';
      Promise.all([read('index.json'), read('by-prefix/' + bucket.toString(16).padStart(2, '0') + '.json')]).then(([index, rows]) => {
        const row = rows.find(r => r[0] === id);
        if (!row) { result.textContent = 'No match for ' + id + ' in the register snapshot of ' + index.asOf + '.'; return; }
        const fields = [['Filed', day(row[3])], ['Approved', day(row[10])], ['Issued', day(row[4])], ['Completed', day(row[5])],
          ['Recorded status', index.statuses[row[2]] || 'Unrecorded'], ['Status date', day(row[6])],
          ['Filing to approval', interval(row[11])], ['Filing to issuance', interval(row[7])], ['Age of open application', interval(row[8])], ['Filing to terminal status', interval(row[12])]];
        result.innerHTML = '<h2>Permit ' + esc(id) + '</h2><p>' + esc(reasons[index.classifications[row[9]]] || '') + '</p><dl>' +
          fields.map(([k, v]) => '<div><dt>' + esc(k) + '</dt><dd>' + esc(v) + '</dd></div>').join('') +
          '</dl><p class="small">Calendar days. Open age is measured on ' + esc(index.asOf) + '.</p>';
      }).catch(() => {
        result.textContent = 'The permit records could not be loaded. Open the full CSV below or retry the lookup on the hosted site.';
      });
    });
    return head('Building permits', 'Look up a permit’s timeline', 'Find filing, issuance, completion and status dates by permit number. The register measures elapsed calendar time, including any time spent with the applicant.') +
      '<section class="card pad"><form id="permit-time-form" class="filters"><label for="permit-time-id">Permit number</label><input id="permit-time-id" name="permit" type="search" required maxlength="12" autocomplete="off" value="' + esc(id) + '"><button class="btn" type="submit">Look up</button></form><div id="permit-time-result" class="section permit-timing-result" aria-live="polite"></div>' +
      '<p><a href="' + path + 'permits.csv.gz" download>Download every permit timeline (CSV, gzip)</a> · <a href="#s/permit_metrics">Compare review times</a></p></section>';
  }

  /* ---------- hand the helpers to the second module (plan, trace, outcomes, extra screens) ---------- */
  const FDX = window.FDX; if (FDX) FDX.init({ C, esc, money, full, tier, head, stat, chartBox, tableOf, after, need, S, fmtDate, dept, byId, main, slugOf, rerender });
  const FDY = window.FDY && C.desks ? window.FDY : null; if (FDY) FDY.init({ C, esc, money, full, tier, head, after, need, byId, slugOf, fmtDate, caseCard, S, rerender });
  const xt = k => (FDX && C.hasDeep ? FDX.tabs[k] : []);

  /* ---------- router ---------- */
  const FEED = !!(window.FDR && window.FDR.has(C));
  // the description of each records page ships in its own bundle (build_site.py → pages.js); only topic, records and search pages wait for it
  let pageText = !C.pageText; const needPages = () => pageText ? null : need(C.pageText).then(P => { (C.desks || []).forEach((d, i) => d.pages.forEach((p, j) => { if (P && P[i] && P[i][j] != null) p[2] = P[i][j]; })); pageText = true; }, () => {});
  const PAGE_TEXT = { topic: 1, search: 1, outcomes: 1, money: 1, contracts: 1, health: 1, screens: 1 };
  const NAV = FDY ? [...(FEED ? [['', 'Watch'], ['briefing', 'Briefing']] : [['', 'Briefing']]), ['cases', 'Cases'], ...(C.hasMap ? [['map', 'Map']] : []), ['topics', 'Topics'], ['orgs', 'Look up'], ...(FDX && C.plan ? [['plan', 'Plan']] : []), ...(C.wanted ? [['wanted', 'Requested data']] : [])] : [['', 'Briefing'], ['cases', 'Cases'], ['orgs', 'Organizations'], ['money', 'Influence'], ['contracts', 'Contracts'], ['method', 'Method']];
  document.getElementById('nav').innerHTML = NAV.map(([k, t]) => `<a href="#${k}" data-nav="${k}">${t}</a>`).join('');
  /* anything that scrolls sideways (the tab bar on a phone, sub-tabs, wide tables) fades at the edge where more is hidden */
  const edges = el => { const f = () => { const m = el.scrollWidth - el.clientWidth; el.classList.toggle('fl', m > 2 && el.scrollLeft > 2); el.classList.toggle('fr', m > 2 && el.scrollLeft < m - 2); }; if (!el.dataset.edges) { el.dataset.edges = 1; el.addEventListener('scroll', f, { passive: true }); } f(); };
  const navEl = document.getElementById('nav'), navMore = document.getElementById('navmore');
  if (navMore) navMore.addEventListener('click', () => navEl.scrollBy({ left: Math.max(120, navEl.clientWidth * .6) }));
  const navShow = () => { const cur = navEl.querySelector('[aria-current]'); if (cur && navEl.scrollWidth > navEl.clientWidth) { const l = cur.offsetLeft - navEl.offsetLeft, r = l + cur.offsetWidth; if (l < navEl.scrollLeft || r > navEl.scrollLeft + navEl.clientWidth - 48) navEl.scrollLeft = l - (navEl.clientWidth - cur.offsetWidth) / 2; } edges(navEl); };
  let rz; window.addEventListener('resize', () => { clearTimeout(rz); rz = setTimeout(() => { edges(navEl); main.querySelectorAll('.table-wrap, .desk-nav ul').forEach(edges); }, 150); });
  const OLD = { overview: '', leads: 'cases', trails: 'cases', records: 'orgs', methodology: 'method', political: 'money', bidding: 'contracts', explorer: 'orgs' };
  let route = '', arg = '';
  async function render(scroll = true) {
    const [path, query = ''] = location.hash.slice(1).split('?'); let [r, a = ''] = path.split('/'); try { a = decodeURIComponent(a); } catch { a = ''; }
    if (r in OLD) r = OLD[r];
    if (r === 'archive') { main.innerHTML = `${head('Archive', esc(a), 'This page belonged to the original, unverified research, which is not published on this site.')}<a class="btn" href="#">Back to the films</a>`; return; }
    const p = new URLSearchParams(query);
    if (r !== route || a !== arg) { S.q = p.get('q') || ''; S.page = 1; S.tier = p.get('tier') || ''; S.phase = p.get('phase') || ''; S.sig = p.get('sig') || ''; S.pat = ''; S.cat = ''; S.tab = ''; }
    if (p.has('phase')) S.phase = p.get('phase'); if (p.has('tier')) S.tier = p.get('tier');          // a filter in the address always wins, even on the same page
    if (window.FDR) window.FDR.leave(); document.body.classList.toggle('feed-on', FEED && (r === '' || r === 'watch'));
    route = r; arg = a; after.length = 0; window.FDC.hideTip(); let html = '', nav = r;
    try {
      if (FDY && PAGE_TEXT[r]) await needPages();
      if ((r === '' || r === 'watch') && FEED) { html = window.FDR.render(C, a, p.get('tier') || ''); after.push(() => window.FDR.mount(C)); nav = ''; }
      else if (r === '' || r === 'briefing') { html = briefing(); nav = FEED ? 'briefing' : ''; }
      else if (r === 'cases') html = (a === 'federal' && FDX && FDX.prosecutions && C.hasProsecutions && await FDX.prosecutions()) || casesPage() + (FDX && C.hasProsecutions ? `<p style="margin-top:22px"><a class="btn" href="#cases/federal">Federal prosecutions and settlements, by subject →</a></p>` : '');
      else if (r === 'case') { html = byId[a] ? casePage(byId[a]) : notFound(); nav = 'cases'; }
      else if (r === 'permit-time') { html = permitTimePage(a); nav = 'topics'; }
      else if (r === 'patterns') html = patternsPage();
      else if (r === 'pattern') { html = patternsPage(a); nav = 'patterns'; }
      else if (r === 'orgs') html = orgsPage(await need('orgs'));
      else if (r === 'org') { html = orgPage(await need('orgs'), a); nav = 'orgs'; }
      else if (r === 'screens') { html = screensPage(await need('orgs'), a); nav = 'orgs'; }
      else if (r === 'plan' && FDX && C.plan) html = FDX.plan();
      else if (r === 'trace' && FDX && C.hasTrace) html = await FDX.trace(a);
      else if (r === 'outcomes' && FDX && C.hasDeep) html = await FDX.outcomes(a);
      else if (r === 'money') html = FDX && FDX.has(r, a) ? await FDX.page(r, a, MONEY_TABS) : moneyPage(await need('ledgers'), a);
      else if (r === 'contracts') html = FDX && FDX.has(r, a) ? await FDX.page(r, a, CONTRACT_TABS) : contractsPage(await need('ledgers'), a);
      else if (r === 'map') { const M = C.hasMap ? await need('map') : null; html = !M ? notFound() : (FDX && FDX.map && a !== 'layers' && FDX.map(M, a)) || mapPage(M); }
      else if (r === 'health') html = C.hasHealth ? healthPage(await need('health'), a) : notFound();
      else if (r === 'who') { html = whoPage(a); nav = 'trace'; }
      else if (r === 'connections') { html = connectionsPage(); nav = 'trace'; }
      else if (r === 'search') html = searchPage(await need('orgs'));
      else if (r === 'method') html = methodPage(a);
      else if (r === 'wanted' && FDY && C.wanted) html = (await FDY.wanted()) || notFound();
      else if (r === 'officials' && FDY) html = (await FDY.officials()) || notFound();
      else if (r === 'official' && FDY) html = (await FDY.official(a)) || notFound();
      else if (r === 'topics' && FDY) html = FDY.topics();
      else if (r === 'topic' && FDY) html = FDY.topic(a) || notFound();
      else if (r === 's' && FDY) html = (await FDY.screen(a)) || notFound();
      else html = notFound();
      if (FDY && !document.body.classList.contains('feed-on')) { html = FDY.frame(r, a, html); nav = FDY.navOf(r, a) || nav; }
    } catch (e) { html = `<div class="empty"><h2>Could not show this page</h2><p>${esc(e.message)}</p></div>`; console.error(e); }
    document.body.classList.toggle('desk-on', html.startsWith('<div class="desk">')); main.innerHTML = html; after.forEach(f => { try { f(); } catch (e) { console.error(e); } });
    document.querySelectorAll('[data-nav]').forEach(n => n.dataset.nav === nav ? n.setAttribute('aria-current', 'page') : n.removeAttribute('aria-current'));
    if (!document.body.classList.contains('feed-on')) document.title = `${main.querySelector('h1')?.textContent || 'Briefing'} — SF Money Trail`;
    if (scroll) { window.scrollTo(0, 0); main.focus({ preventScroll: true }); }
    navShow(); requestAnimationFrame(() => main.querySelectorAll('.table-wrap, .desk-nav ul').forEach(edges));
  }
  function rerender(focusId) { const el = focusId && document.getElementById(focusId), pos = el ? el.selectionStart : null; render(false).then(() => { if (focusId) { const n = document.getElementById(focusId); if (n) { n.focus(); if (pos != null && n.setSelectionRange) n.setSelectionRange(pos, pos); } } }); }
  window.addEventListener('hashchange', () => render());
  document.getElementById('gs').addEventListener('submit', e => { e.preventDefault(); location.hash = '#search?q=' + encodeURIComponent(document.getElementById('gq').value); });
  document.getElementById('theme').addEventListener('click', () => { const r = document.documentElement, dark = r.dataset.theme ? r.dataset.theme === 'dark' : matchMedia('(prefers-color-scheme: dark)').matches; r.dataset.theme = dark ? 'light' : 'dark'; try { localStorage.setItem('fd-theme', r.dataset.theme); } catch { } });
  try { const t = localStorage.getItem('fd-theme'); if (t) document.documentElement.dataset.theme = t; } catch { }
  { const t = new URLSearchParams(location.search).get('theme'); if (t === 'light' || t === 'dark') document.documentElement.dataset.theme = t; }
  document.getElementById('edition').textContent = fmtDate(C.edition);
  render(false);
})();
